        request$ = this.http.post<T>(url, body, httpOptions);
        break;
      case 'PUT':
        request$ = this.http.put<T>(url, body, httpOptions);
        break;
      case 'PATCH':
        request$ = this.http.patch<T>(url, body, httpOptions);
        break;
      case 'DELETE':
        request$ = this.http.delete<T>(url, httpOptions);
        break;
      default:
        throw new Error(`Unsupported HTTP method: ${method}`);
    }

    return request$.pipe(
      retry(retryCount),
      catchError(this.handleError.bind(this))
    );
  }

  /**
   * Construye la URL completa
   */
  private buildUrl(endpoint: string): string {
    if (endpoint.startsWith('http://') || endpoint.startsWith('https://')) {
      return endpoint; // URL absoluta
    }
    const cleanEndpoint = endpoint.startsWith('/') ? endpoint : `/${endpoint}`;
    return `${this.baseUrl}${cleanEndpoint}`;
  }

  /**
   * Construye los headers de la petición
   */
  private buildHeaders(customHeaders?: HttpHeaders | Record<string, string | string[]>): HttpHeaders {
    let headers = new HttpHeaders(this.defaultHeaders);

    if (customHeaders) {
      if (customHeaders instanceof HttpHeaders) {
        customHeaders.keys().forEach(key => {
          headers = headers.set(key, customHeaders.get(key) || '');
        });
      } else {
        Object.entries(customHeaders).forEach(([key, value]) => {
          headers = headers.set(key, value);
        });
      }
    }

    return headers;
  }

  /**
   * Maneja errores HTTP
   */
  private handleError(error: HttpErrorResponse): Observable<never> {
    const apiError: ApiError = {
      message: this.extractErrorMessage(error),
      status: error.status,
      statusText: error.statusText,
      url: error.url,
      errors: error.error?.errors
    };

    console.error('[ApiService] Error:', apiError);
    return throwError(() => apiError);
  }

  /**
   * Extrae mensaje de error legible
   */
  private extractErrorMessage(error: HttpErrorResponse): string {
    if (error.status === 0) {
      return 'No se pudo conectar con el servidor. Verifica tu conexión a internet.';
    }

    if (error.error?.message) {
      return error.error.message;
    }

    if (typeof error.error === 'string') {
      return error.error;
    }

    switch (error.status) {
      case 400: return 'Solicitud inválida';
      case 401: return 'No autorizado. Por favor inicia sesión.';
      case 403: return 'Acceso denegado';
      case 404: return 'Recurso no encontrado';
      case 422: return 'Datos de entrada inválidos';
      case 429: return 'Demasiadas solicitudes. Intenta más tarde.';
      case 500: return 'Error interno del servidor';
      case 502: return 'Servidor no disponible';
      case 503: return 'Servicio temporalmente no disponible';
      default: return `Error ${error.status}: ${error.statusText}`;
    }
  }
}

import { Injectable, signal, computed } from '@angular/core';
import { Observable, Subscription } from 'rxjs';
import { ApiError } from './api.service';

/**
 * Estado de una petición API
 */
export interface ApiState<T> {
  data: T | null;
  loading: boolean;
  error: ApiError | null;
}

/**
 * Resultado del hook useApi
 */
export interface UseApiResult<T> {
  /** Signal con los datos de la respuesta */
  data: () => T | null;
  /** Signal que indica si está cargando */
  loading: () => boolean;
  /** Signal con el error si existe */
  error: () => ApiError | null;
  /** Signal computed que indica si la petición fue exitosa */
  success: () => boolean;
  /** Signal computed que indica si hay error */
  hasError: () => boolean;
  /** Ejecuta una petición */
  execute: (request: Observable<T>) => Subscription;
  /** Resetea el estado */
  reset: () => void;
  /** Actualiza los datos manualmente */
  setData: (data: T) => void;
}

/**
 * Hook signal-based para consumir APIs con estado reactivo.
 * 
 * @example
 * ```typescript
 * // En tu componente
 * private api = inject(ApiService);
 * private userApi = useApi<User[]>();
 * 
 * // Acceso a signals
 * users = this.userApi.data;
 * loading = this.userApi.loading;
 * error = this.userApi.error;
 * 
 * // Ejecutar petición
 * loadUsers() {
 *   this.userApi.execute(this.api.get('/users'));
 * }
 * 
 * // En template
 * @if (loading()) {
 *   <app-loader></app-loader>
 * } @else if (error()) {
 *   <p>Error: {{ error()?.message }}</p>
 * } @else {
 *   @for (user of users(); track user.id) {
 *     <p>{{ user.name }}</p>
 *   }
 * }
 * ```
 */
export function useApi<T>(initialData: T | null = null): UseApiResult<T> {
  const data = signal<T | null>(initialData);
  const loading = signal<boolean>(false);
  const error = signal<ApiError | null>(null);

  const success = computed(() => data() !== null && !loading() && !error());
  const hasError = computed(() => error() !== null);

  let currentSubscription: Subscription | null = null;

  const execute = (request: Observable<T>): Subscription => {
    // Cancel previous request if exists
    if (currentSubscription) {
      currentSubscription.unsubscribe();
    }

    loading.set(true);
    error.set(null);

    currentSubscription = request.subscribe({
      next: (result) => {
        data.set(result);
        loading.set(false);
      },
      error: (err: ApiError) => {
        error.set(err);
        loading.set(false);
      }
    });

    return currentSubscription;
  };

  const reset = (): void => {
    if (currentSubscription) {
      currentSubscription.unsubscribe();
      currentSubscription = null;
    }
    data.set(initialData);
    loading.set(false);
    error.set(null);
  };

  const setData = (newData: T): void => {
    data.set(newData);
    error.set(null);
  };

  return {
    data: data.asReadonly(),
    loading: loading.asReadonly(),
    error: error.asReadonly(),
    success,
    hasError,
    execute,
    reset,
    setData
  };
}

/**
 * Servicio inyectable alternativo para usar con DI.
 * Útil cuando necesitas compartir estado entre componentes.
 * 
 * @example
 * ```typescript
 * // Crear servicio específico
 * @Injectable({ providedIn: 'root' })
 * export class UsersApiService extends UseApiService<User[]> {
 *   private api = inject(ApiService);
 *   
 *   loadUsers() {
 *     this.execute(this.api.get('/users'));
 *   }
 * }
 * ```
 */
@Injectable()
export class UseApiService<T> {
  private readonly _data = signal<T | null>(null);
  private readonly _loading = signal<boolean>(false);
  private readonly _error = signal<ApiError | null>(null);
  private subscription: Subscription | null = null;

  readonly data = this._data.asReadonly();
  readonly loading = this._loading.asReadonly();
  readonly error = this._error.asReadonly();
  readonly success = computed(() => this._data() !== null && !this._loading() && !this._error());
  readonly hasError = computed(() => this._error() !== null);

  execute(request: Observable<T>): Subscription {
    if (this.subscription) {
      this.subscription.unsubscribe();
    }

    this._loading.set(true);
    this._error.set(null);

    this.subscription = request.subscribe({
      next: (result) => {
        this._data.set(result);
        this._loading.set(false);
      },
      error: (err: ApiError) => {
        this._error.set(err);
        this._loading.set(false);
      }
    });

    return this.subscription;
  }

  reset(): void {
    if (this.subscription) {
      this.subscription.unsubscribe();
      this.subscription = null;
    }
    this._data.set(null);
    this._loading.set(false);
    this._error.set(null);
  }

  setData(data: T): void {
    this._data.set(data);
    this._error.set(null);
  }
}

import { Injectable, InjectionToken, inject, signal } from '@angular/core';

export interface AppVersionInfo {
  appName: string;
  version: string;
  environment: string;
  buildDate: string;
  isNative: boolean;
}

/**
 * Adaptador opcional proporcionado por cada consumidor.
 *
 * Atomic UI no detecta Tauri, Wails ni PyWebView. El runtime propietario
 * traduce sus metadatos al contrato visual común y los inyecta al arrancar.
 */
export const APP_VERSION_INFO = new InjectionToken<Partial<AppVersionInfo>>(
  'ATOMIC_APP_VERSION_INFO'
);

const DEFAULT_VERSION_INFO: AppVersionInfo = {
  appName: '',
  version: 'v1.0.0',
  environment: 'BETA',
  buildDate: '',
  isNative: false
};

@Injectable({
  providedIn: 'root'
})
export class AppVersionService {
  private readonly providedInfo = inject(APP_VERSION_INFO, { optional: true });

  readonly versionInfo = signal<AppVersionInfo>({
    ...DEFAULT_VERSION_INFO,
    ...this.providedInfo
  });

  setVersionInfo(info: Partial<AppVersionInfo>): void {
    this.versionInfo.update((current) => ({ ...current, ...info }));
  }
}

import { Component, ChangeDetectionStrategy, input } from '@angular/core';

import { AvatarComponent } from '../../atoms/avatar/avatar.component';
import { VariablesCssDirective } from '../../directives/variables-css.directive';

export interface AvatarGroupItem {
  name: string;
  initials?: string;
  photo?: string;
  color?: string;
  status?: 'online' | 'offline' | 'away' | 'busy';
  tooltip?: string;
}

/**
 * AvatarGroupComponent — Stack de avatares superpuestos.
 * Muestra los primeros `max` avatares y un contador "+N" si hay más.
 *
 * @example
 * ```html
 * <app-avatar-group [items]="collaborators" [max]="4" size="sm"></app-avatar-group>
 * ```
 */
@Component({
  selector: 'app-avatar-group',
  standalone: true,
  imports: [AvatarComponent, VariablesCssDirective],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <div class="avatar-group" [class]="'avatar-group-' + size()">
      @for (item of visible; track item.name; let i = $index) {
        <div
          class="avatar-group-item"
          [appVariablesCss]="{ '--avatar-stack-order': visible.length - i }"
          [title]="item.tooltip || item.name"
        >
          <app-avatar
            [initials]="item.initials || getInitials(item.name)"
            [src]="item.photo"
            [status]="item.status"
            [size]="size()"
            [color]="item.color"
          ></app-avatar>
        </div>
      }
      @if (overflow > 0) {
        <div class="avatar-group-item avatar-group-overflow" [title]="'+' + overflow + ' más'">
          <div class="overflow-badge" [class]="'overflow-' + size()">+{{ overflow }}</div>
        </div>
      }
    </div>
  `,
  styleUrl: './avatar-group.component.css'
})
export class AvatarGroupComponent {
  /** Lista completa de avatares */
  readonly items = input<AvatarGroupItem[]>([]);

  /** Máximo de avatares visibles antes de mostrar contador */
  readonly max = input(5);

  /** Tamaño de los avatares */
  readonly size = input<'sm' | 'md' | 'lg' | 'xl'>('md');

  get visible(): AvatarGroupItem[] {
    return this.items().slice(0, this.max());
  }

  get overflow(): number {
    return Math.max(0, this.items().length - this.max());
  }

  getInitials(name: string): string {
    return name
      .split(' ')
      .slice(0, 2)
      .map(n => n[0])
      .join('')
      .toUpperCase();
  }
}

