/*
Normaliza para comparar: separa los diacríticos de su letra (NFD), los retira, y
minusculiza con las reglas del español. Colapsa además los espacios, para que
«San  Juan» y «San Juan» sean lo mismo al buscar.

El rango ̀-ͯ es el bloque de marcas diacríticas combinantes, que es lo
que NFD deja suelto detrás de cada letra acentuada.
*/
function normalizeSearch(value: string): string {
  return value
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .toLocaleLowerCase('es')
    .replace(/\s+/g, ' ')
    .trim();
}

/**
 * ComboboxComponent — Input con sugerencias de autocompletado.
 *
 * @example
 * ```html
 * <app-combobox
 *   [options]="userOptions"
 *   [(ngModel)]="selectedUser"
 *   label="Buscar usuario"
 *   placeholder="Escribe para buscar..."
 * ></app-combobox>
 * ```
 */
@Component({
  selector: 'app-combobox',
  standalone: true,
  imports: [FormsModule],
  changeDetection: ChangeDetectionStrategy.OnPush,
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: forwardRef(() => ComboboxComponent),
      multi: true
    }
  ],
  template: `
    <div class="combobox" [class.combobox-open]="isOpen()" [class.combobox-disabled]="disabled">
      @if (label()) {
        <label class="combobox-label" [for]="inputId">{{ label() }}</label>
      }
      <div class="combobox-control" #controlRef>
        <input
          #inputRef
          [id]="inputId"
          class="combobox-input"
          type="text"
          [placeholder]="placeholder()"
          [disabled]="disabled"
          [value]="inputValue()"
          (input)="onInput($event)"
          (focus)="onFocus()"
          (blur)="onBlur()"
          (keydown)="onKeydown($event)"
          autocomplete="off"
          role="combobox"
          [attr.aria-expanded]="isOpen()"
          aria-autocomplete="list"
          [attr.aria-controls]="listboxId"
          [attr.aria-activedescendant]="activeOptionId()"
          [attr.aria-label]="label() ? null : ariaLabel() || placeholder()"
          [attr.aria-invalid]="error() ? 'true' : 'false'"
          [attr.aria-errormessage]="error() ? errorId : null"
          aria-haspopup="listbox"
