    );
  }

  protected identifyRow(index: number, row: T): unknown {
    return this.trackBy()(index, row);
  }

  protected getBadgeStatus(column: DataTableColumn<T>, row: T): StatusBadgeStatus {
    if (column.badgeStatus) {
