    next.set(code, this.normalizeQuantity(value));
    this.quantities.set(next);
    this.onTouched();
    this.emitValue();
  }

  confirmCurrentValue(): void {
    if (this.isDisabled() || this.state() !== 'suggested' || this.total() <= 0) {
      return;
    }

    this.onTouched();
    this.emitValue();
  }

