  private requestedPosition = { left: VIEWPORT_PADDING, top: VIEWPORT_PADDING };
  private generation = 0;
  private pendingOperationGeneration: number | null = null;
  private layoutFrame: number | null = null;
  private readonly controlRevisions = new WeakMap<TextControl, number>();
  private registered = false;
  private readonly capturedScrollListener = (event: Event) => {
    const node = event.target;
    if (node instanceof Node && this.menuRef?.nativeElement.contains(node)) {
      return;
    }
    if (this.isOpen()) {
      this.closeMenu();
    }
  };
  private readonly visualViewportResizeListener = () => {
    if (this.isOpen()) {
      this.repositionMenu();
    }
  };
  private readonly capturedContextMenuListener = (event: MouseEvent) => this.onContextMenu(event);
  private readonly capturedKeydownListener = (event: KeyboardEvent) => this.onHostKeydown(event);
  private readonly capturedClipboardListener = (event: ClipboardEvent) =>
    this.onProtectedClipboardEvent(event);
  private readonly capturedBeforeInputListener = (event: InputEvent) =>
    this.onProtectedBeforeInput(event);
  private readonly capturedDragStartListener = (event: DragEvent) =>
    this.onProtectedDragStart(event);
  private readonly capturedPointerDownListener = (event: PointerEvent) =>
    this.onDocumentPointerDown(event);
  private readonly capturedInputListener = (event: Event) => this.onControlInput(event);
  private readonly capturedFocusInListener = (event: FocusEvent) => this.onDocumentFocusIn(event);

  ngOnChanges(changes: SimpleChanges): void {
    if (changes['disabled'] && this.disabled() && this.isOpen()) {
      this.closeMenu();
      return;
    }
    if (!changes['disabledActions'] || !this.isOpen()) {
      return;
    }
    const current = this.activeAction();
    const next =
      current && !this.isActionDisabled(current) ? current : (this.navigationActions()[0] ?? null);
    this.activeAction.set(next);
    if (!this.target) {
      return;
    }
    if (next) {
      this.target.setAttribute('aria-activedescendant', this.itemId(next));
    } else {
      this.target.removeAttribute('aria-activedescendant');
    }
  }

  ngOnInit(): void {
    const instances = ContextMenuComponent.documentInstances.get(this.document) ?? [];
    instances.push(this);
    ContextMenuComponent.documentInstances.set(this.document, instances);
    this.registered = true;
    this.document.addEventListener('scroll', this.capturedScrollListener, true);
    this.document.addEventListener('contextmenu', this.capturedContextMenuListener, true);
    this.document.addEventListener('keydown', this.capturedKeydownListener, true);
    this.document.addEventListener('copy', this.capturedClipboardListener, true);
    this.document.addEventListener('cut', this.capturedClipboardListener, true);
    this.document.addEventListener('beforeinput', this.capturedBeforeInputListener, true);
    this.document.addEventListener('dragstart', this.capturedDragStartListener, true);
    this.document.addEventListener('pointerdown', this.capturedPointerDownListener, true);
    this.document.addEventListener('input', this.capturedInputListener, true);
    this.document.addEventListener('focusin', this.capturedFocusInListener, true);
    const visualViewport = this.document.defaultView?.visualViewport;
    visualViewport?.addEventListener('scroll', this.capturedScrollListener);
    visualViewport?.addEventListener('resize', this.visualViewportResizeListener);
  }

  ngOnDestroy(): void {
    if (this.registered) {
      this.document.removeEventListener('scroll', this.capturedScrollListener, true);
      this.document.removeEventListener('contextmenu', this.capturedContextMenuListener, true);
      this.document.removeEventListener('keydown', this.capturedKeydownListener, true);
      this.document.removeEventListener('copy', this.capturedClipboardListener, true);
      this.document.removeEventListener('cut', this.capturedClipboardListener, true);
      this.document.removeEventListener('beforeinput', this.capturedBeforeInputListener, true);
      this.document.removeEventListener('dragstart', this.capturedDragStartListener, true);
      this.document.removeEventListener('pointerdown', this.capturedPointerDownListener, true);
      this.document.removeEventListener('input', this.capturedInputListener, true);
      this.document.removeEventListener('focusin', this.capturedFocusInListener, true);
      const visualViewport = this.document.defaultView?.visualViewport;
      visualViewport?.removeEventListener('scroll', this.capturedScrollListener);
      visualViewport?.removeEventListener('resize', this.visualViewportResizeListener);
      const instances = ContextMenuComponent.documentInstances.get(this.document) ?? [];
      const remaining = instances.filter((instance) => instance !== this);
      if (remaining.length === 0) {
        ContextMenuComponent.documentInstances.delete(this.document);
      } else {
        ContextMenuComponent.documentInstances.set(this.document, remaining);
      }
      this.registered = false;
    }
    this.closeMenu();
  }

  itemId(action: ContextMenuAction): string {
    return `${this.menuId}-${action}`;
  }

  setActiveAction(action: ContextMenuAction): void {
    if (this.menuItems.some((item) => item.action === action) && !this.isActionDisabled(action)) {
      this.activeAction.set(action);
      this.target?.setAttribute('aria-activedescendant', this.itemId(action));
    }
  }

  preserveTargetFocus(event: PointerEvent): void {
    event.preventDefault();
  }

  onContextMenu(event: MouseEvent): void {
    if (!this.isDocumentController()) {
      return;
    }
    if (this.menuRef?.nativeElement.contains(event.target as Node)) {
      event.preventDefault();
      return;
    }

    if (this.disabled()) {
      this.closeMenu();
      return;
    }

    const target = this.resolveTextControl(event.target);
    if (!target) {
      this.closeMenu();
      return;
    }

    event.preventDefault();
    event.stopPropagation();
    const point = this.resolveOpeningPoint(event.clientX, event.clientY, target);
    this.openMenu(target, point.left, point.top);
  }

  onHostKeydown(event: KeyboardEvent): void {
    if (!this.isDocumentController()) {
      return;
    }
    const clipboardKey = event.key.toLowerCase();
    if (
      this.isProtectedContext(event.target) &&
      (event.ctrlKey || event.metaKey) &&
      (clipboardKey === 'c' || clipboardKey === 'x')
    ) {
      this.blockEvent(event);
      return;
    }

    if (this.isOpen()) {
      if (this.isMenuInteractionKey(event.key)) {
        this.onMenuKeydown(event);
        return;
      }
      if (this.isEditingKey(event)) {
        this.closeMenu();
        return;
      }
      return;
    }

    const isContextMenuKey = event.key === 'ContextMenu';
    const isShiftF10 = event.shiftKey && event.key === 'F10';
    if (this.disabled() || (!isContextMenuKey && !isShiftF10)) {
      return;
    }

    const target = this.resolveTextControl(event.target);
    if (!target) {
      return;
    }

    event.preventDefault();
    event.stopPropagation();
    const rect = target.getBoundingClientRect();
    this.openMenu(target, rect.left, rect.bottom);
  }

  onProtectedClipboardEvent(event: ClipboardEvent): void {
    if (!this.isDocumentController()) {
      return;
    }
    if (this.isProtectedContext(event.target)) {
      this.blockEvent(event);
      return;
    }
    if (this.isOpen() && this.isCurrentTextTarget(event.target)) {
      this.closeMenu();
    }
  }

  onProtectedBeforeInput(event: InputEvent): void {
    if (!this.isDocumentController()) {
      return;
    }
    if (event.inputType === 'deleteByCut' && this.isProtectedContext(event.target)) {
      this.blockEvent(event);
      return;
    }
    if (this.isOpen() && this.isCurrentTextTarget(event.target)) {
      this.closeMenu();
    }
  }

  onProtectedDragStart(event: DragEvent): void {
    if (this.isDocumentController() && this.isProtectedContext(event.target)) {
      this.blockEvent(event);
    }
  }

  onControlInput(event: Event): void {
    if (!this.isDocumentController()) {
      return;
    }
    const target = this.resolveTextControl(event.target);
    if (target) {
      if (this.isOpen() && target === this.target) {
        this.closeMenu();
      }
      this.controlRevisions.set(target, this.controlRevision(target) + 1);
    }
  }

  onDocumentPointerDown(event: PointerEvent): void {
    if (!this.isDocumentController()) {
      return;
    }

    if (!this.isOpen()) {
      if (this.pendingOperationGeneration !== null) {
        this.generation += 1;
        this.pendingOperationGeneration = null;
      }
      return;
    }

    const node = event.target as Node | null;
    if (node && !this.menuRef?.nativeElement.contains(node)) {
      this.closeMenu();
    }
  }

  onDocumentFocusIn(event: FocusEvent): void {
    if (!this.isDocumentController() || !this.isOpen()) {
      return;
    }
    const node = event.target as Node | null;
    if (
      node &&
      node !== this.target &&
      !this.target?.contains(node) &&
      !this.menuRef?.nativeElement.contains(node)
    ) {
      this.closeMenu();
    }
  }

  @HostListener('window:resize')
  onViewportResize(): void {
    if (this.isDocumentController() && this.isOpen()) {
      this.repositionMenu();
    }
  }

  suppressNestedContextMenu(event: MouseEvent): void {
    event.preventDefault();
    event.stopPropagation();
  }

  isActionDisabled(action: ContextMenuAction): boolean {
    if (this.disabled() || this.disabledActions().includes(action) || !this.target || !this.selection) {
      return true;
    }

    switch (action) {
      case 'cut':
        return (
          this.hasPasteOnlyPolicy(this.target) ||
          !this.isWritable(this.target) ||
          !this.hasSelectedText(this.selection)
        );
      case 'copy':
        return this.hasPasteOnlyPolicy(this.target) || !this.hasSelectedText(this.selection);
      case 'paste':
        return !this.isWritable(this.target);
      case 'select-all':
        return this.selection.textLength === 0;
    }
  }

  async executeAction(action: ContextMenuAction): Promise<void> {
    const target = this.target;
    const selection = this.selection;
    if (!target || !selection || this.isActionDisabled(action)) {
      return;
    }

    const operationGeneration = this.generation;
    let detached = false;

    try {
      this.assertOperationTarget(target, selection, operationGeneration);
      this.pendingOperationGeneration = operationGeneration;
      this.restoreSelection(target, selection);
      this.detachMenuForOperation();
      detached = true;
      switch (action) {
        case 'cut':
          await this.cut(target, selection, operationGeneration);
          break;
        case 'copy':
          await this.copy(target, selection);
          break;
        case 'paste':
          await this.paste(target, selection, operationGeneration);
          break;
        case 'select-all':
          this.selectAll(target);
          break;
      }
      this.actionSelected.emit(action);
      if (operationGeneration === this.generation) {
        this.feedback.set(this.successFeedback(action));
      }
    } catch (reason: unknown) {
      if (!detached && this.target === target) {
        this.closeMenu();
      }
      const failureReason = this.failureReason(reason);
      this.actionError.emit({ action, reason: failureReason });
      if (operationGeneration === this.generation) {
        this.feedback.set(this.failureFeedback(failureReason));
      }
    } finally {
      if (this.pendingOperationGeneration === operationGeneration) {
        this.pendingOperationGeneration = null;
      }
      this.releaseSelection(selection);
    }
  }

  onMenuKeydown(event: KeyboardEvent): void {
    if (event.key === 'Escape') {
      event.preventDefault();
      event.stopPropagation();
      this.closeMenu(true);
      return;
    }

    if (event.key === 'Tab') {
      this.closeMenu();
      return;
    }

    const actions = this.navigationActions();
    if (actions.length === 0) {
      return;
    }

    const activeIndex = actions.indexOf(this.activeAction() as ContextMenuAction);
    let nextIndex: number | null = null;

    switch (event.key) {
      case 'Enter':
      case ' ':
        event.preventDefault();
        event.stopPropagation();
        void this.executeAction(actions[activeIndex < 0 ? 0 : activeIndex]!);
        return;
      case 'ArrowDown':
      case 'ArrowRight':
        nextIndex = activeIndex < 0 ? 0 : (activeIndex + 1) % actions.length;
        break;
      case 'ArrowUp':
      case 'ArrowLeft':
        nextIndex = activeIndex <= 0 ? actions.length - 1 : activeIndex - 1;
        break;
      case 'Home':
        nextIndex = 0;
        break;
      case 'End':
        nextIndex = actions.length - 1;
        break;
    }

    if (nextIndex !== null) {
      event.preventDefault();
      event.stopPropagation();
      const action = actions[nextIndex];
      if (action) {
        this.setActiveAction(action);
      }
    }
  }

  /** Recalcula la posición con las dimensiones reales del menú. */
  repositionMenu(): void {
    const menu = this.menuRef?.nativeElement;
    const view = this.document.defaultView;
    if (!menu || !view) {
      return;
    }

    const rect = menu.getBoundingClientRect();
    const visualViewport = view.visualViewport;
    const viewportLeft = visualViewport?.offsetLeft ?? 0;
    const viewportTop = visualViewport?.offsetTop ?? 0;
    const viewportWidth =
      visualViewport?.width || this.document.documentElement.clientWidth || view.innerWidth;
    const viewportHeight =
      visualViewport?.height || this.document.documentElement.clientHeight || view.innerHeight;
    const width = rect.width || menu.offsetWidth;
    const height = rect.height || menu.offsetHeight;
    const minLeft = viewportLeft + VIEWPORT_PADDING;
    const minTop = viewportTop + VIEWPORT_PADDING;
    const maxLeft = Math.max(minLeft, viewportLeft + viewportWidth - width - VIEWPORT_PADDING);
    const maxTop = Math.max(minTop, viewportTop + viewportHeight - height - VIEWPORT_PADDING);
    const left = this.clamp(this.requestedPosition.left, minLeft, maxLeft);
    const top = this.clamp(this.requestedPosition.top, minTop, maxTop);

    menu.style.left = `${left}px`;
    menu.style.top = `${top}px`;
    this.position.set({ left, top });
  }

  private openMenu(target: TextControl, left: number, top: number): void {
    if (this.isOpen() || this.target || this.selection) {
      this.closeMenu();
    }
    const openingGeneration = ++this.generation;
    this.target = target;
    this.selection = this.captureSelection(target);
    this.requestedPosition = { left, top };
    this.position.set({
      left: Math.max(VIEWPORT_PADDING, left),
      top: Math.max(VIEWPORT_PADDING, top),
    });
    this.isOpen.set(true);
    this.feedback.set('Menú de edición abierto.');
    const firstAction = this.navigationActions()[0] ?? null;
    this.activeAction.set(firstAction);
    this.attachTargetAria(target, firstAction);

    this.scheduleMenuLayout(openingGeneration);
  }

  private closeMenu(restoreFocus = false, invalidateGeneration = true): void {
    const target = this.target;
    const selection = this.selection;
    if (restoreFocus && target && selection) {
      this.restoreSelection(target, selection);
    }
    this.restoreTargetAria(target);
    this.cancelMenuLayout();
    this.isOpen.set(false);
    this.activeAction.set(null);
    this.target = null;
    this.selection = null;
    this.releaseSelection(selection);
    if (invalidateGeneration) {
      this.generation += 1;
      this.pendingOperationGeneration = null;
    }
  }

  private detachMenuForOperation(): void {
    this.restoreTargetAria(this.target);
    this.cancelMenuLayout();
    this.isOpen.set(false);
    this.activeAction.set(null);
    this.target = null;
    this.selection = null;
  }

  private navigationActions(): ContextMenuAction[] {
    return this.menuItems
      .map((item) => item.action)
      .filter((action) => !this.isActionDisabled(action));
  }

  private scheduleMenuLayout(openingGeneration: number, retries = 1): void {
    this.cancelMenuLayout();
    const view = this.document.defaultView;
    if (!view?.requestAnimationFrame) {
      queueMicrotask(() => this.repositionMenu());
      return;
    }
    this.layoutFrame = view.requestAnimationFrame(() => {
      this.layoutFrame = null;
      if (!this.isOpen() || openingGeneration !== this.generation) {
        return;
      }
      if (!this.menuRef && retries > 0) {
        this.scheduleMenuLayout(openingGeneration, retries - 1);
        return;
      }
      this.repositionMenu();
    });
  }

  private cancelMenuLayout(): void {
    if (this.layoutFrame === null) {
      return;
    }
    this.document.defaultView?.cancelAnimationFrame(this.layoutFrame);
    this.layoutFrame = null;
  }

  private resolveTextControl(eventTarget: EventTarget | null): TextControl | null {
    if (!(eventTarget instanceof Element)) {
      return null;
    }

    const policyElement = eventTarget.closest<HTMLElement>(`[${CONTEXT_MENU_POLICY_ATTRIBUTE}]`);
    const policy = policyElement?.getAttribute(CONTEXT_MENU_POLICY_ATTRIBUTE);
    if (policy === NATIVE_POLICY) {
      return null;
    }
    const explicitlyManaged = policy === TEXT_EDIT_POLICY;

    const nativeControl = eventTarget.closest<HTMLInputElement | HTMLTextAreaElement>(
      'textarea, input',
    );
    if (nativeControl?.isConnected) {
      if (nativeControl.disabled) {
        return null;
      }
      if (nativeControl instanceof HTMLInputElement && !TEXT_INPUT_TYPES.has(nativeControl.type)) {
        return null;
      }
      if (
        !explicitlyManaged &&
        (nativeControl.getAttribute('role') === 'combobox' ||
          nativeControl.hasAttribute('aria-controls') ||
          nativeControl.hasAttribute('aria-haspopup'))
      ) {
        return null;
      }
      return nativeControl;
    }

    let candidate: Element | null = eventTarget;
    while (candidate?.isConnected) {
      if (candidate.hasAttribute('contenteditable')) {
        const mode = (candidate.getAttribute('contenteditable') ?? '').toLowerCase();
        if (mode === 'false') {
          return null;
        }
        if (mode === '' || mode === 'true' || mode === 'plaintext-only') {
          return explicitlyManaged ? (candidate as HTMLElement) : null;
        }
      }
      candidate = candidate.parentElement;
    }
    return null;
  }

  private isDocumentController(): boolean {
    if (!this.registered) {
      return false;
    }
    const instances = ContextMenuComponent.documentInstances.get(this.document) ?? [];
    const controller = instances.find((instance) => instance.registered);
    if (controller !== this && this.isOpen()) {
      this.closeMenu();
    }
    if (controller !== this && this.pendingOperationGeneration !== null) {
      this.generation += 1;
      this.pendingOperationGeneration = null;
    }
    return controller === this;
  }

  private hasPasteOnlyPolicy(eventTarget: EventTarget | null): boolean {
    if (!(eventTarget instanceof Element)) {
      return false;
    }

    const passwordInput = eventTarget.closest<HTMLInputElement>('input[type="password"]');
    if (passwordInput?.isConnected) {
      return true;
    }

    const protectedTarget = eventTarget.closest<HTMLElement>(
      '[data-clipboard-policy="paste-only"]',
    );
    return Boolean(protectedTarget?.isConnected);
  }

  private isProtectedContext(eventTarget: EventTarget | null): boolean {
    return (
      this.hasPasteOnlyPolicy(eventTarget) ||
      Boolean(this.isOpen() && this.target && this.hasPasteOnlyPolicy(this.target))
    );
  }

  private isCurrentTextTarget(eventTarget: EventTarget | null): boolean {
    return (
      eventTarget instanceof Node &&
      Boolean(this.target && (eventTarget === this.target || this.target.contains(eventTarget)))
    );
  }

  private isEditingKey(event: KeyboardEvent): boolean {
    const key = event.key.toLowerCase();
    if (key === 'backspace' || key === 'delete' || event.isComposing) {
      return true;
    }
    if ((event.ctrlKey || event.metaKey) && ['a', 'c', 'v', 'x', 'y', 'z'].includes(key)) {
      return true;
    }
    return event.key.length === 1 && !event.metaKey && (!event.ctrlKey || event.altKey);
  }

  private isMenuInteractionKey(key: string): boolean {
    return [
      'Escape',
      'Tab',
      'ArrowDown',
      'ArrowRight',
      'ArrowUp',
      'ArrowLeft',
      'Home',
      'End',
      'Enter',
      ' ',
    ].includes(key);
  }

  private blockEvent(event: Event): void {
    event.preventDefault();
    event.stopImmediatePropagation();
  }

  private resolveOpeningPoint(
    clientX: number,
    clientY: number,
    target: TextControl,
  ): { left: number; top: number } {
    if (clientX !== 0 || clientY !== 0) {
      return { left: clientX, top: clientY };
    }

    const rect = target.getBoundingClientRect();
    return { left: rect.left, top: rect.bottom };
  }

  private captureSelection(target: TextControl): SelectionSnapshot {
    if (target instanceof HTMLInputElement || target instanceof HTMLTextAreaElement) {
      const selectionSupported = target.selectionStart !== null && target.selectionEnd !== null;
      const start = target.selectionStart ?? target.value.length;
      const end = target.selectionEnd ?? start;
      return {
        kind: 'input',
        start,
        end,
        direction: target.selectionDirection ?? 'none',
        selectionSupported,
        textLength: target.value.length,
        revision: this.controlRevision(target),
      };
    }

    const selection = this.document.defaultView?.getSelection();
    const activeRange = selection && selection.rangeCount > 0 ? selection.getRangeAt(0) : null;
    const range =
      activeRange && target.contains(activeRange.commonAncestorContainer)
        ? activeRange.cloneRange()
        : null;
    return {
      kind: 'editable',
      range,
      textLength: target.textContent?.length ?? 0,
      revision: this.controlRevision(target),
    };
  }

  private restoreSelection(target: TextControl, snapshot: SelectionSnapshot): void {
    if (!target.isConnected) {
      return;
    }
    this.focusTarget(target);
    if (snapshot.kind === 'input') {
      if (target instanceof HTMLInputElement || target instanceof HTMLTextAreaElement) {
        if (!snapshot.selectionSupported) {
          return;
        }
        try {
          target.setSelectionRange(snapshot.start, snapshot.end, snapshot.direction);
        } catch {
          return;
        }
      }
      return;
    }

    if (!snapshot.range || !snapshot.range.startContainer.isConnected) {
      return;
    }
    const selection = this.document.defaultView?.getSelection();
    selection?.removeAllRanges();
    selection?.addRange(snapshot.range);
  }

  private hasSelectedText(snapshot: SelectionSnapshot): boolean {
    return snapshot.kind === 'input'
      ? snapshot.end > snapshot.start
      : Boolean(snapshot.range && !snapshot.range.collapsed);
  }

  private selectedText(target: TextControl, snapshot: SelectionSnapshot): string {
    if (snapshot.kind === 'input') {
      return target instanceof HTMLInputElement || target instanceof HTMLTextAreaElement
        ? target.value.slice(snapshot.start, snapshot.end)
        : '';
    }
    return snapshot.range?.toString() ?? '';
  }

  private isWritable(target: TextControl): boolean {
    if (target instanceof HTMLInputElement || target instanceof HTMLTextAreaElement) {
      return !target.disabled && !target.readOnly;
    }
    return target.getAttribute('contenteditable') !== 'false';
  }

  private attachTargetAria(target: TextControl, activeAction: ContextMenuAction | null): void {
    this.targetAria = {
      controls: target.getAttribute('aria-controls'),
      expanded: target.getAttribute('aria-expanded'),
      haspopup: target.getAttribute('aria-haspopup'),
      activeDescendant: target.getAttribute('aria-activedescendant'),
    };
    target.setAttribute('aria-controls', this.menuId);
    target.setAttribute('aria-expanded', 'true');
    target.setAttribute('aria-haspopup', 'menu');
    if (activeAction) {
      target.setAttribute('aria-activedescendant', this.itemId(activeAction));
    } else {
      target.removeAttribute('aria-activedescendant');
    }
  }

  private restoreTargetAria(target: TextControl | null): void {
    const snapshot = this.targetAria;
    this.targetAria = null;
    if (!target || !snapshot) {
      return;
    }
    this.restoreAttribute(target, 'aria-controls', snapshot.controls);
    this.restoreAttribute(target, 'aria-expanded', snapshot.expanded);
    this.restoreAttribute(target, 'aria-haspopup', snapshot.haspopup);
    this.restoreAttribute(target, 'aria-activedescendant', snapshot.activeDescendant);
  }

  private restoreAttribute(target: HTMLElement, name: string, value: string | null): void {
    if (value === null) {
      target.removeAttribute(name);
    } else {
      target.setAttribute(name, value);
    }
  }

  private releaseSelection(snapshot: SelectionSnapshot | null): void {
    if (snapshot?.kind === 'editable') {
      snapshot.range?.detach();
      snapshot.range = null;
    }
  }

  private async copy(target: TextControl, selection: SelectionSnapshot): Promise<void> {
    if (this.executeDocumentCommand('copy')) {
      return;
    }
    const clipboard = this.resolveBrowserClipboard();
    if (!clipboard) {
      throw new ContextMenuOperationError('clipboard-unavailable');
    }
    let text = this.selectedText(target, selection);
    try {
      await clipboard.writeText(text);
    } catch {
      throw new ContextMenuOperationError('clipboard-denied');
    } finally {
      text = '';
    }
  }

  private async cut(
    target: TextControl,
    selection: SelectionSnapshot,
    operationGeneration: number,
  ): Promise<void> {
    if (this.executeDocumentCommand('cut')) {
      return;
    }
    const clipboard = this.resolveBrowserClipboard();
    if (!clipboard) {
      throw new ContextMenuOperationError('clipboard-unavailable');
    }
    let text = this.selectedText(target, selection);
    try {
      await clipboard.writeText(text);
    } catch {
      throw new ContextMenuOperationError('clipboard-denied');
    } finally {
      text = '';
    }
    this.assertOperationTarget(target, selection, operationGeneration);
    if (!this.deleteSelection(target, selection)) {
      throw new ContextMenuOperationError('operation-failed');
    }
  }

  private async paste(
    target: TextControl,
    selection: SelectionSnapshot,
    operationGeneration: number,
  ): Promise<void> {
    const clipboard = this.resolveBrowserClipboard();
    if (!clipboard) {
      if (this.executeDocumentCommand('paste')) {
        return;
      }
      throw new ContextMenuOperationError('clipboard-unavailable');
    }

    let text = '';
    try {
      text = await clipboard.readText();
    } catch {
      throw new ContextMenuOperationError('clipboard-denied');
    }
    try {
      this.assertOperationTarget(target, selection, operationGeneration);
      if (!this.insertText(target, selection, text)) {
        throw new ContextMenuOperationError('operation-failed');
      }
    } finally {
      text = '';
    }
  }

  private deleteSelection(target: TextControl, selection: SelectionSnapshot): boolean {
    if (!this.dispatchBeforeInputEvent(target, 'deleteByCut')) {
      return false;
    }
    if (selection.kind === 'input') {
      if (target instanceof HTMLInputElement || target instanceof HTMLTextAreaElement) {
        if (selection.selectionSupported) {
          target.setRangeText('', selection.start, selection.end, 'start');
        } else {
          target.value = target.value.slice(0, selection.start) + target.value.slice(selection.end);
        }
        this.dispatchInputEvent(target, 'deleteByCut');
        return true;
      }
      return false;
    }

    if (!selection.range) {
      return false;
    }
    selection.range.deleteContents();
    this.dispatchInputEvent(target, 'deleteByCut');
    return true;
  }

  private insertText(
    target: TextControl,
    selection: SelectionSnapshot,
    clipboardText: string,
  ): boolean {
    const text = this.truncatePasteText(target, selection, clipboardText);
    if (text.length === 0 && !this.hasSelectedText(selection)) {
      return true;
    }
    if (!this.dispatchBeforeInputEvent(target, 'insertFromPaste', text)) {
      return false;
    }
    if (selection.kind === 'input') {
      if (target instanceof HTMLInputElement || target instanceof HTMLTextAreaElement) {
        if (selection.selectionSupported) {
          target.setRangeText(text, selection.start, selection.end, 'end');
        } else {
          target.value =
            target.value.slice(0, selection.start) + text + target.value.slice(selection.end);
        }
        this.dispatchInputEvent(target, 'insertFromPaste', text);
        return true;
      }
      return false;
    }

    const range = selection.range ?? this.document.createRange();
    if (!selection.range) {
      range.selectNodeContents(target);
      range.collapse(false);
    } else {
      range.deleteContents();
    }
    const textNode = this.document.createTextNode(text);
    range.insertNode(textNode);
    range.setStartAfter(textNode);
    range.collapse(true);
    const browserSelection = this.document.defaultView?.getSelection();
    browserSelection?.removeAllRanges();
    browserSelection?.addRange(range);
    this.dispatchInputEvent(target, 'insertFromPaste', text);
    return true;
  }

  private selectAll(target: TextControl): void {
    this.focusTarget(target);
    if (target instanceof HTMLInputElement || target instanceof HTMLTextAreaElement) {
      target.select();
      return;
    }

    const range = this.document.createRange();
    range.selectNodeContents(target);
    const selection = this.document.defaultView?.getSelection();
    selection?.removeAllRanges();
    selection?.addRange(range);
  }

  private resolveBrowserClipboard(): Clipboard | null {
    try {
      return this.document.defaultView?.navigator.clipboard ?? null;
    } catch {
      return null;
    }
  }

  private focusTarget(target: TextControl): void {
    try {
      target.focus({ preventScroll: true });
    } catch {
      target.focus();
    }
  }

  private executeDocumentCommand(command: 'copy' | 'cut' | 'paste'): boolean {
    try {
      return typeof this.document.execCommand === 'function' && this.document.execCommand(command);
    } catch {
      return false;
    }
  }

  private dispatchBeforeInputEvent(
    target: TextControl,
    inputType: 'deleteByCut' | 'insertFromPaste',
    data: string | null = null,
  ): boolean {
    const InputEventConstructor = this.document.defaultView?.InputEvent;
    const event = InputEventConstructor
      ? new InputEventConstructor('beforeinput', {
          bubbles: true,
          cancelable: true,
          data,
          inputType,
        })
      : new Event('beforeinput', { bubbles: true, cancelable: true });
    return target.dispatchEvent(event);
  }

  private dispatchInputEvent(
    target: TextControl,
    inputType: 'deleteByCut' | 'insertFromPaste',
    data: string | null = null,
  ): void {
    const InputEventConstructor = this.document.defaultView?.InputEvent;
    const event = InputEventConstructor
      ? new InputEventConstructor('input', { bubbles: true, data, inputType })
      : new Event('input', { bubbles: true });
    target.dispatchEvent(event);
  }

  private truncatePasteText(
    target: TextControl,
    selection: SelectionSnapshot,
    text: string,
  ): string {
    const normalizedText =
      target instanceof HTMLInputElement ? text.replace(/\r\n?|\n/g, ' ') : text;
    if (
      selection.kind !== 'input' ||
      !(target instanceof HTMLInputElement || target instanceof HTMLTextAreaElement) ||
      target.maxLength < 0
    ) {
      return normalizedText;
    }
    const selectedLength = selection.end - selection.start;
    const capacity = Math.max(0, target.maxLength - (target.value.length - selectedLength));
    return normalizedText.slice(0, capacity);
  }

  private assertOperationTarget(
    target: TextControl,
    selection: SelectionSnapshot,
    operationGeneration: number,
  ): void {
    const activeElement = this.document.activeElement;
    if (
      operationGeneration !== this.generation ||
      !target.isConnected ||
      (activeElement !== target && !target.contains(activeElement)) ||
      selection.revision !== this.controlRevision(target)
    ) {
      throw new ContextMenuOperationError('target-changed');
    }

    if (selection.kind === 'input') {
      if (
        !(target instanceof HTMLInputElement || target instanceof HTMLTextAreaElement) ||
        target.value.length !== selection.textLength ||
        (selection.selectionSupported &&
          (target.selectionStart !== selection.start || target.selectionEnd !== selection.end))
      ) {
        throw new ContextMenuOperationError('target-changed');
      }
      return;
    }

    const range = selection.range;
    const browserSelection = this.document.defaultView?.getSelection();
    const currentRange = browserSelection?.rangeCount ? browserSelection.getRangeAt(0) : null;
    if (
      !range ||
      !range.startContainer.isConnected ||
      target.textContent?.length !== selection.textLength ||
      !currentRange ||
      currentRange.startContainer !== range.startContainer ||
      currentRange.startOffset !== range.startOffset ||
      currentRange.endContainer !== range.endContainer ||
      currentRange.endOffset !== range.endOffset
    ) {
      throw new ContextMenuOperationError('target-changed');
    }
  }

  private controlRevision(target: TextControl): number {
    return this.controlRevisions.get(target) ?? 0;
  }

  private failureReason(reason: unknown): ContextMenuFailureReason {
    return reason instanceof ContextMenuOperationError ? reason.reason : 'operation-failed';
  }

  private successFeedback(action: ContextMenuAction): string {
    switch (action) {
      case 'cut':
        return 'Texto cortado.';
      case 'copy':
        return 'Texto copiado.';
      case 'paste':
        return 'Texto pegado.';
      case 'select-all':
        return 'Texto seleccionado.';
    }
  }

  private failureFeedback(reason: ContextMenuFailureReason): string {
    switch (reason) {
      case 'clipboard-unavailable':
        return 'El portapapeles no está disponible.';
      case 'clipboard-denied':
        return 'El sistema no permitió acceder al portapapeles.';
      case 'target-changed':
        return 'La acción se canceló porque el control cambió.';
      case 'operation-failed':
        return 'No se pudo completar la acción de edición.';
    }
  }

  private clamp(value: number, minimum: number, maximum: number): number {
    return Math.min(Math.max(value, minimum), maximum);
  }
}

import { Component, inject, signal, computed, OnInit } from '@angular/core';
import { Router } from '@angular/router';

import { FormBuilder, ReactiveFormsModule, FormsModule, Validators } from '@angular/forms';
import { SidebarMenuItem,
  PanelComponent,
  ButtonComponent,
  AvatarComponent,
  ChoiceControl,
  Select2Component,
  TableComponent,
  TableHeadComponent,
  TableRowComponent,
  TableCellComponent,
  RowComponent,
  TextComponent,
  ChipComponent,
  ActionGroupComponent,
  ActionItem,
  PaginationComponent,
  DataPagerComponent,
  LayoutShellComponent,
  SidebarComponent,
  TopbarComponent,
  ThemeSwitcherComponent,

  ModalComponent,
  FloatingInputComponent,
  LoaderComponent
} from '@shared/ui';
import { ApiService } from '@shared/ui/services/api.service';
import { useApi } from '@shared/ui/services/use-api.service';

import { of, delay } from 'rxjs';

export interface Entity {
  id: string;
  name: string;
  email: string;
  role: string;
  status: string;
  createdAt: string;
}

export interface FilterOptions {
  searchType: string;
  searchValue: string;
  status: string;
  role: string;
}

export interface PaginatedResponse<T> {
  data: T[];
  meta: {
    total: number;
    page: number;
    perPage: number;
    totalPages: number;
  };
}

const FAKE_DB: Entity[] = Array.from({ length: 50 }).map((_, i) => ({
  id: String(i + 1),
  name: `Usuario de Prueba ${i + 1}`,
  email: `usuario${i + 1}@example.com`,
  role: i % 3 === 0 ? 'admin' : i % 2 === 0 ? 'editor' : 'user',
  status: i % 5 === 0 ? 'inactive' : i % 7 === 0 ? 'pending' : 'active',
  createdAt: new Date(Date.now() - Math.floor(Math.random() * 10000000000)).toISOString().split('T')[0]
}));
let idCounter = 51;

/**
 * CRUD Table Blueprint
 * 
 * Features:
 * - Data table with pagination
 * - Search and filter functionality
 * - Create/Edit modal
 * - Delete confirmation
 * - Bulk actions
 * - Loading and error states
 * - Responsive design
 * 
 * @usage
 * 1. Copy this folder to your project
 * 2. Rename Entity interface to your model (User, Product, etc.)
 * 3. Configure API endpoints
 * 4. Adjust table columns
 */
@Component({
  selector: 'app-crud-table',
  standalone: true,
  imports: [
    ReactiveFormsModule,
    FormsModule,
    PanelComponent,
    ButtonComponent,
    FloatingInputComponent,
    Select2Component,
    PaginationComponent,
    DataPagerComponent,
    LayoutShellComponent,
    SidebarComponent,
    TopbarComponent,
    ThemeSwitcherComponent,
    ModalComponent,
    AvatarComponent,
    ChoiceControl,
    ChipComponent,
    LoaderComponent,
    ActionGroupComponent,
    TableComponent,
    TableHeadComponent,
    TableRowComponent,
    TableCellComponent,
    RowComponent,
    TextComponent
],
  templateUrl: './crud-table.component.html',
  styleUrl: './crud-table.component.css'
})
export class CrudTableComponent implements OnInit {
  // SIDEBAR
  sidebarVisible = signal(true);
  menuItems: SidebarMenuItem[] = [
    { label: 'Showcase', icon: 'fa-solid fa-palette', route: '/showcase' , iconColor: 'var(--secondary-color)' },
    { label: 'Dashboard', icon: 'fa-solid fa-chart-pie', route: '/dashboard' , iconColor: 'var(--info-color)' },
    { label: 'CRUD', icon: 'fa-solid fa-table', route: '/crud' , iconColor: 'var(--success-color)' },
    { label: 'Perfil', icon: 'fa-solid fa-user', route: '/profile' , iconColor: 'var(--warning-color)' },
    { label: 'Settings', icon: 'fa-solid fa-cog', route: '/settings' , iconColor: 'var(--danger-color)' },
  ];

  onToggleSidebar() {
    this.sidebarVisible.update(v => !v);
  }

  onSidebarNavigate(item: SidebarMenuItem) {
    if (item.route) {
      this.router.navigate([item.route]);
    }
  }

  onLogout() {
    alert('Cerrando sesión...');
    this.router.navigate(['/login']);
  }

  private readonly fb = inject(FormBuilder).nonNullable;
  private readonly router = inject(Router);
  private api = inject(ApiService);

  // Table actions configuration
  tableActions: ActionItem[] = [
    { id: 'edit', icon: 'fa-solid fa-pen', label: 'Editar', variant: 'primary' },
    { id: 'delete', icon: 'fa-solid fa-trash', label: 'Eliminar', variant: 'danger' }
  ];

  onRowAction(actionId: string, item: Entity) {
    if (actionId === 'edit') {
      this.openEditModal(item);
    } else if (actionId === 'delete') {
      this.openDeleteModal(item);
    }
  }

  // ============================================
  // CONFIGURATION - Customize these values
  // ============================================

  /** @customize API endpoint for CRUD operations */
  private readonly ENDPOINT = '/users';

  /** @customize Items per page */
  pageSize = signal(10);

  /** @customize Table title */
  readonly TABLE_TITLE = 'Usuarios';

  /** @customize Entity name (singular) */
  readonly ENTITY_NAME = 'Usuario';

  // ============================================
  // STATE
  // ============================================

  private _searchTimeout?: ReturnType<typeof setTimeout>;

  /** List API state */
  listApi = useApi<PaginatedResponse<Entity>>();

  /** Create/Update API state */
  saveApi = useApi<Entity>();

  /** Delete API state */
  deleteApi = useApi<{ success: boolean }>();

  /** Current page */
  currentPage = signal(1);

  /** Search term */
  searchTerm = signal('');

  /** Active filters */
  filters = signal<FilterOptions>({
    searchType: '',
    searchValue: '',
    status: '',
    role: ''
  });

  /** Selected items for bulk actions */
  selectedItems = signal<Set<string | number>>(new Set());

  /** All items selected flag */
  allSelected = signal(false);

  /** Modal visibility */
  showModal = signal(false);

  /** Delete confirmation modal */
  showDeleteModal = signal(false);

  /** Item to delete */
  itemToDelete = signal<Entity | null>(null);

  /** Edit mode flag */
  isEditMode = signal(false);

  /** Current editing item */
  currentItem = signal<Entity | null>(null);

  // ============================================
  // FILTER OPTIONS
  // ============================================

  /** @customize Status options for filter */

  searchTypeOptions = [
    { value: '', label: 'Seleccione' },
    { value: 'name', label: 'Nombre del personal' },
    { value: 'document', label: 'Número de documento' },
    { value: 'regimen', label: 'Régimen laboral' },
    { value: 'status', label: 'Estado' }
  ];

  regimenOptions = [
    { value: '', label: 'Seleccione' },
    { value: '728', label: 'D.L. 728' },
    { value: '1057', label: 'CAS' },
    { value: '276', label: 'D.L. 276' }
  ];

  selectedSearchType = signal('');
  searchValue = signal('');

  statusOptions = [
    { value: '', label: 'Todos los estados' },
    { value: 'active', label: 'Activo' },
    { value: 'inactive', label: 'Inactivo' },
    { value: 'pending', label: 'Pendiente' }
  ];

  /** @customize Role options for filter */
  roleOptions = [
    { value: '', label: 'Todos los roles' },
    { value: 'admin', label: 'Administrador' },
    { value: 'user', label: 'Usuario' },
    { value: 'guest', label: 'Invitado' }
  ];

  // ============================================
  // FORM
  // ============================================

  entityForm = this.fb.group({
    name: ['', [Validators.required, Validators.minLength(2)]],
    email: ['', [Validators.required, Validators.email]],
    role: ['user', [Validators.required]],
    status: ['active', [Validators.required]]
  });

  // ============================================
  // COMPUTED
  // ============================================

  /** Current page data */
  items = computed(() => this.listApi.data()?.data ?? []);

  /** Pagination meta */
  meta = computed(() => this.listApi.data()?.meta ?? {
    total: 0,
    page: 1,
    perPage: this.pageSize(),
    totalPages: 1
  });

  /** Number of selected items */
  selectedCount = computed(() => this.selectedItems().size);

  /** Has selected items */
  hasSelection = computed(() => this.selectedCount() > 0);

  // ============================================
  // LIFECYCLE
  // ============================================

  ngOnInit(): void {
    this.loadData();
  }

  // ============================================
  // DATA LOADING
  // ============================================

  loadData(): void {
    const filters = this.filters();
    let filtered = [...FAKE_DB];
    if (filters.searchType && filters.searchValue) {
      const type = filters.searchType;
      const val = filters.searchValue.toLowerCase();
      if (type === 'name') filtered = filtered.filter(e => e.name.toLowerCase().includes(val) || e.email.toLowerCase().includes(val));
      if (type === 'document') filtered = filtered.filter(e => e.id.toLowerCase().includes(val)); // Mock document as id
      if (type === 'regimen') {
        // Mock regimen logic (we don't have regimen in Entity, let's map it randomly or just skip)
        // Let's pretend everyone with role admin is 728, others are CAS (1057)
        filtered = filtered.filter(e => (val === '728' ? e.role === 'admin' : e.role !== 'admin'));
      }
      if (type === 'status') filtered = filtered.filter(e => e.status === val);
    }
    if (filters.status) filtered = filtered.filter(e => e.status === filters.status);
    if (filters.role) filtered = filtered.filter(e => e.role === filters.role);

    const page = this.currentPage();
    const perPage = this.pageSize();
    const start = (page - 1) * perPage;
    const paginated = filtered.slice(start, start + perPage);

    const res: PaginatedResponse<Entity> = {
      data: paginated,
      meta: { total: filtered.length, page, perPage, totalPages: Math.ceil(filtered.length / perPage) }
    };

    this.listApi.execute(of(res).pipe(delay(600)));
  }

  // ============================================
  // PAGINATION
  // ============================================

  onPageChange(page: number): void {
    this.currentPage.set(page);
    this.clearSelection();
    this.loadData();
  }

  // ============================================
  // SEARCH & FILTERS
  // ============================================

  applySearch(): void {
    this.filters.update(f => ({ ...f, searchType: this.selectedSearchType(), searchValue: this.searchValue() }));
    this.currentPage.set(1);
    this.loadData();
  }

  onSearchTypeChange(type: string): void {
    this.selectedSearchType.set(type);
    this.searchValue.set(''); // clear value when type changes
    this.applySearch();
  }

  onSearchValueChange(val: string): void {
    this.searchValue.set(val);
    clearTimeout(this._searchTimeout);
    this._searchTimeout = setTimeout(() => {
      this.applySearch();
    }, 300);
  }

  onStatusFilter(status: string): void {
    this.filters.update(f => ({ ...f, status }));
    this.currentPage.set(1);
    this.loadData();
  }

  onRoleFilter(role: string): void {
    this.filters.update(f => ({ ...f, role }));
    this.currentPage.set(1);
    this.loadData();
  }

  clearFilters(): void {
    this.filters.set({ searchType: '', searchValue: '', status: '', role: '' });
    this.selectedSearchType.set(''); this.searchValue.set('');
    this.currentPage.set(1);
    this.loadData();
  }

  hasActiveFilters(): boolean {
    const f = this.filters();
    return !!(f.searchType || f.searchValue || f.status || f.role);
  }

  // ============================================
  // SELECTION
  // ============================================

  toggleSelectAll(): void {
    if (this.allSelected()) {
      this.clearSelection();
    } else {
      const allIds = new Set<string | number>(this.items().map(item => item.id));
      this.selectedItems.set(allIds);
      this.allSelected.set(true);
    }
  }

  toggleSelect(item: Entity): void {
    const selected = new Set(this.selectedItems());
    if (selected.has(item.id)) {
      selected.delete(item.id);
    } else {
      selected.add(item.id);
    }
    this.selectedItems.set(selected);
    this.allSelected.set(selected.size === this.items().length);
  }

  isSelected(item: Entity): boolean {
    return this.selectedItems().has(item.id);
  }

  clearSelection(): void {
    this.selectedItems.set(new Set());
    this.allSelected.set(false);
  }

  // ============================================
  // CREATE / EDIT
  // ============================================

  openCreateModal(): void {
    this.isEditMode.set(false);
    this.currentItem.set(null);
    this.entityForm.reset({
      name: '',
      email: '',
      role: 'user',
      status: 'active'
    });
    this.showModal.set(true);
  }

  openEditModal(item: Entity): void {
    this.isEditMode.set(true);
    this.currentItem.set(item);
    this.entityForm.patchValue({
      name: item.name,
      email: item.email,
      role: item.role,
      status: item.status
    });
    this.showModal.set(true);
  }

  closeModal(): void {
    this.showModal.set(false);
    this.saveApi.reset();
  }

  onSave(): void {
    if (this.entityForm.invalid) {
      this.entityForm.markAllAsTouched();
      return;
    }

    const formValue = this.entityForm.getRawValue();
    const currentItem = this.currentItem();
    const data: Entity = {
      id: currentItem?.id ?? String(idCounter++),
      createdAt: currentItem?.createdAt ?? new Date().toISOString().split('T')[0],
      ...formValue,
    };

    if (this.isEditMode()) {
      const item = currentItem;
      if (item) {
        const idx = FAKE_DB.findIndex(e => e.id === item.id);
        if (idx !== -1) FAKE_DB[idx] = data;
        this.saveApi.execute(of(data).pipe(delay(800)));
      }
    } else {
      FAKE_DB.unshift(data);
      this.saveApi.execute(of(data).pipe(delay(800)));
    }

    // Check for success
    const checkSave = setInterval(() => {
      if (this.saveApi.success()) {
        clearInterval(checkSave);
        this.closeModal();
        this.loadData();
      }
    }, 100);
  }

  // ============================================
  // DELETE
  // ============================================

  openDeleteModal(item: Entity): void {
    this.itemToDelete.set(item);
    this.showDeleteModal.set(true);
  }

  closeDeleteModal(): void {
    this.showDeleteModal.set(false);
    this.itemToDelete.set(null);
    this.deleteApi.reset();
  }

  confirmDelete(): void {
    const item = this.itemToDelete();
    if (item) {
      const idx = FAKE_DB.findIndex(e => e.id === item.id);
      if (idx !== -1) { FAKE_DB.splice(idx, 1); }
      this.deleteApi.execute(of({ success: true }).pipe(delay(600)));
      const checkDelete = setInterval(() => {
        if (this.deleteApi.success()) {
          clearInterval(checkDelete);
          this.closeDeleteModal();
          this.loadData();
        }
      }, 100);
    }
  }

  // ============================================
  // BULK ACTIONS
  // ============================================

  bulkDelete(): void {
    const ids = Array.from(this.selectedItems());
    if (ids.length === 0) return;

    // TODO: Implement bulk delete API call
    // Example: this.api.post('/bulk-delete', { ids }).subscribe(() => this.loadData());
    this.clearSelection();
  }

  bulkExport(): void {
    const _ids = Array.from(this.selectedItems());
    // TODO: Implement export functionality
    // Example: this.api.downloadFile('/export', { ids: ids.length > 0 ? ids : 'all' });
  }

  // ============================================
  // HELPERS
  // ============================================

  getStatusVariant(status: string): 'success' | 'warning' | 'error' | 'default' {
    switch (status) {
      case 'active': return 'success';
      case 'pending': return 'warning';
      case 'inactive': return 'error';
      default: return 'default';
    }
  }

  getStatusLabel(status: string): string {
    switch (status) {
      case 'active': return 'Activo';
      case 'pending': return 'Pendiente';
      case 'inactive': return 'Inactivo';
      default: return status;
    }
  }

  // ============================================
  // NAVIGATION
  // ============================================

  onPageSizeChange(newSize: number): void {
    this.pageSize.set(newSize);
    this.currentPage.set(1);
    this.loadData();
  }

  goBack(): void {
    this.router.navigate(['/']);
  }

  formatDate(dateString: string): string {
    return new Date(dateString).toLocaleDateString('es-ES', {
      year: 'numeric',
      month: 'short',
      day: 'numeric'
    });
  }

  getFieldError(fieldName: string): string {
    const field = this.entityForm.get(fieldName);
    if (!field || !field.touched || !field.errors) return '';

    if (field.errors['required']) return 'Campo requerido';
    if (field.errors['email']) return 'Email inválido';
    if (field.errors['minlength']) {
      return `Mínimo ${field.errors['minlength'].requiredLength} caracteres`;
    }
    return '';
  }
}

import { Component, Input, OnInit, inject } from '@angular/core';

import { ActivatedRoute, Router } from '@angular/router';
import {
  ButtonComponent,
  TextComponent,
  ScrollOverlayComponent,
  RowComponent,
} from '@shared/ui';

export type ErrorCode = 400 | 401 | 403 | 404 | 500 | 503;

export interface ErrorPageConfig {
  code: ErrorCode;
  title: string;
  description: string;
  icon: string;
  primaryAction?: { label: string; route: string };
  secondaryAction?: { label: string; action: () => void };
}

const ERROR_DEFAULTS: Record<ErrorCode, Omit<ErrorPageConfig, 'primaryAction' | 'secondaryAction'>> = {
  400: {
    code: 400,
    title: 'Solicitud inválida',
    description: 'La solicitud enviada no es válida. Verifica los datos ingresados e intenta de nuevo.',
    icon: '⚠️',
  },
  401: {
    code: 401,
    title: 'No autorizado',
    description: 'No tienes credenciales para acceder a este recurso. Inicia sesión para continuar.',
    icon: '🔐',
  },
  403: {
    code: 403,
    title: 'Acceso denegado',
    description: 'No tienes permisos para acceder a esta página. Contacta a tu administrador.',
    icon: '🚫',
  },
  404: {
    code: 404,
    title: 'Página no encontrada',
    description: 'La página que buscas no existe o fue movida. Verifica la URL o vuelve al inicio.',
    icon: '🔍',
  },
  500: {
    code: 500,
    title: 'Error interno del servidor',
    description: 'Ocurrió un error inesperado en el servidor. Por favor intenta más tarde.',
    icon: '💥',
  },
  503: {
    code: 503,
    title: 'Servicio no disponible',
    description: 'El servicio está temporalmente fuera de línea por mantenimiento. Vuelve en unos minutos.',
    icon: '🔧',
  },
};

/**
 * ErrorPagesComponent — Página de error genérica para 400/401/403/404/500/503
 *
 * @usage
 * ```html
 * <!-- En app.routes.ts -->
 * { path: '**', component: ErrorPagesComponent, data: { code: 404 } }
 * { path: '500', component: ErrorPagesComponent, data: { code: 500 } }
 * ```
 *
 * @usage
 * ```html
 * <!-- En template -->
 * <app-error-pages [code]="404"></app-error-pages>
 * <app-error-pages [code]="500" title="Error personalizado"></app-error-pages>
 * ```
 */
@Component({
  selector: 'app-error-pages',
  standalone: true,
  imports: [
    ButtonComponent,
    TextComponent,
  ScrollOverlayComponent,
    RowComponent
],
  template: `
    <app-scroll-overlay class="so-block h-screen w-full" [skipTableDetection]="true">
    <div class="error-page">
      <div class="error-container">

        <!-- Icono / Ilustración -->
        <div class="error-icon" role="img" [attr.aria-label]="'Error ' + resolvedCode()">
          {{ resolvedIcon() }}
        </div>

        <!-- Código HTTP -->
        <div class="error-code">{{ resolvedCode() }}</div>

        <!-- Título -->
        <app-text variant="h2" class="error-title">
          {{ resolvedTitle() }}
        </app-text>

        <!-- Descripción -->
        <app-text variant="body" color="muted" class="error-description">
          {{ resolvedDescription() }}
        </app-text>

        <!-- Acciones -->
        <app-row gap="1rem" class="error-actions">
          <app-button
            variant="primary"
            (click)="onPrimaryAction()"
          >
            <i class="fa-solid fa-house" icon-left></i>
            {{ primaryActionLabel }}
          </app-button>

          @if (showSecondaryAction) {
            <app-button variant="ghost" (click)="onSecondaryAction()">
              <i class="fa-solid fa-arrow-rotate-right" icon-left></i>
              Reintentar
            </app-button>
          }

          <app-button variant="ghost" (click)="goBack()">
            <i class="fa-solid fa-arrow-left" icon-left></i>
            Volver
          </app-button>
        </app-row>

        <!-- Info técnica (solo en development) -->
        @if (showTechnicalInfo && technicalMessage) {
          <details class="error-technical">
            <summary>Información técnica</summary>
            <code>{{ technicalMessage }}</code>
          </details>
        }

      </div>
    </div>
  `,
  styles: [`
    .error-page {
      min-height: 100vh;
      display: flex;
      align-items: center;
      justify-content: center;
      background: var(--page-background, var(--surface-background));
      padding: var(--space-8);
    }

    .error-container {
      max-width: 520px;
      width: 100%;
      text-align: center;
      display: flex;
      flex-direction: column;
      align-items: center;
      gap: var(--space-4);
    }

    .error-icon {
      font-size: 5rem;
      line-height: 1;
      animation: bounce-in 0.5s cubic-bezier(0.34, 1.56, 0.64, 1);
    }

    .error-code {
      font-size: 7rem;
      font-weight: var(--font-weight-display);
      line-height: 1;
      color: var(--primary-color);
      opacity: 0.15;
      letter-spacing: -4px;
      user-select: none;
    }

    .error-title {
      margin-top: calc(-1 * var(--space-8));
    }

    .error-description {
      max-width: 400px;
    }

    .error-actions {
      margin-top: var(--space-2);
      justify-content: center;
      flex-wrap: wrap;
    }

    .error-technical {
      margin-top: var(--space-6);
      text-align: left;
      background: var(--surface-section);
      border: 1px solid var(--border-color);
      border-radius: var(--radius-md);
      padding: var(--space-3) var(--space-4);
      width: 100%;
      font-size: 0.75rem;
    }

    .error-technical summary {
      cursor: pointer;
      color: var(--text-color-muted);
      margin-bottom: var(--space-2);
    }

    .error-technical code {
      font-family: monospace;
      color: var(--color-error);
      word-break: break-all;
    }

    @keyframes bounce-in {
      from { transform: scale(0.5); opacity: 0; }
      to   { transform: scale(1);   opacity: 1; }
    }

    @media (max-width: 30rem) {
      .error-code { font-size: 5rem; }
      .error-icon { font-size: 3.5rem; }
    }
  `],
})
export class ErrorPagesComponent implements OnInit {
  /** HTTP error code to display */
  @Input() code: ErrorCode = 404;

  /** Override default title */
  @Input() title?: string;

  /** Override default description */
  @Input() description?: string;

  /** Override default icon */
  @Input() icon?: string;

  /** Label for primary action button */
  @Input() primaryActionLabel = 'Ir al inicio';

  /** Route for primary action */
  @Input() primaryActionRoute = '/';

  /** Show retry button (useful for 500, 503) */
  @Input() showSecondaryAction = false;

  /** Show technical details section */
  @Input() showTechnicalInfo = false;

  /** Technical error message for developers */
  @Input() technicalMessage?: string;

  private readonly router = inject(Router);
  private readonly route = inject(ActivatedRoute);

  ngOnInit(): void {
    const routeCode = this.route.snapshot.data['code'];
    if (typeof routeCode === 'number') {
      this.code = routeCode as ErrorCode;
    }
  }

  protected resolvedCode(): ErrorCode {
    return this.code;
  }

  protected resolvedTitle(): string {
    return this.title ?? ERROR_DEFAULTS[this.code]?.title ?? 'Error';
  }

  protected resolvedDescription(): string {
    return this.description ?? ERROR_DEFAULTS[this.code]?.description ?? '';
  }

  protected resolvedIcon(): string {
    return this.icon ?? ERROR_DEFAULTS[this.code]?.icon ?? '❌';
  }

  onPrimaryAction(): void {
    this.router.navigate([this.primaryActionRoute]);
  }

  onSecondaryAction(): void {
    window.location.reload();
  }

  goBack(): void {
    history.back();
  }
}

import {
  Component,
  ChangeDetectionStrategy,
  signal,
  inject,
  PLATFORM_ID,
  ViewChild,
  ElementRef,
  ChangeDetectorRef,
  input,
  output
} from '@angular/core';
import { isPlatformBrowser } from '@angular/common';
import { ControlValueAccessor, NG_VALUE_ACCESSOR } from '@angular/forms';

let fileInputSequence = 0;

export interface FileInputFile {
  file: File;
  name: string;
  size: number;
  type: string;
  preview?: string;
}

export type FileInputDensity = 'comfortable' | 'compact';

/**
 * FileInputComponent — Campo de carga de archivos con drag & drop.
 *
 * @example
 * ```html
 * <app-file-input
 *   label="Adjuntar documentos"
 *   accept=".pdf,.docx"
 *   [multiple]="true"
 *   [maxSizeMB]="5"
 *   (filesChange)="onFiles($event)">
 * </app-file-input>
 * ```
 */
@Component({
  selector: 'app-file-input',
  standalone: true,
  imports: [],
  changeDetection: ChangeDetectionStrategy.OnPush,
  providers: [{ provide: NG_VALUE_ACCESSOR, useExisting: FileInputComponent, multi: true }],
  template: `
    <div
      class="file-input-wrapper"
      [class.disabled]="isDisabled()"
      [class.drag-over]="isDragging()"
      [class.invalid]="visibleError"
      [class.compact]="density() === 'compact'"
    >
      @if (label()) {
        <label class="file-label" [for]="inputId">{{ label() }}</label>
      }
      @if (hint()) {
        <p class="file-hint" [id]="inputId + '-hint'">{{ hint() }}</p>
      }
      <div
        class="drop-zone"
        (click)="openFileDialog()"
        (dragover)="onDragOver($event)"
        (dragleave)="isDragging.set(false)"
        (drop)="onDrop($event)"
        (blur)="onTouched()"
        (keydown.enter)="openFileDialog()"
        (keydown.space)="openFileDialog(); $event.preventDefault()"
        [attr.tabindex]="isDisabled() ? -1 : 0"
        role="button"
        [attr.aria-disabled]="isDisabled()"
        [attr.aria-invalid]="visibleError ? 'true' : null"
        [attr.aria-describedby]="
          visibleError ? inputId + '-error' : hint() ? inputId + '-hint' : null
        "
        aria-label="Seleccionar archivo"
      >
        <i class="fa-solid fa-cloud-arrow-up drop-icon" aria-hidden="true"></i>
        <div class="drop-copy">
          <p class="drop-text"><strong>Haz clic</strong> o arrastra archivos aquí</p>
          @if (accept()) {
            <p class="drop-hint">Formatos: {{ accept() }}</p>
          }
          @if (maxSizeMB()) {
            <p class="drop-hint">Máximo {{ maxSizeMB() }} MB por archivo</p>
          }
        </div>
      </div>

      <input
        #fileInput
        [id]="inputId"
        type="file"
        class="file-hidden"
        [accept]="accept()"
        [multiple]="multiple()"
        [disabled]="isDisabled()"
        (change)="onFileChange($event)"
        (blur)="onTouched()"
        [attr.aria-invalid]="visibleError ? 'true' : null"
        [attr.aria-label]="label() || 'Seleccionar archivo'"
        [attr.aria-describedby]="
          visibleError ? inputId + '-error' : hint() ? inputId + '-hint' : null
        "
      />

      @if (visibleError) {
        <p class="file-error" [id]="inputId + '-error'" role="alert">
          <i class="fa-solid fa-circle-exclamation" aria-hidden="true"></i> {{ visibleError }}
        </p>
      }

      @if (files().length > 0) {
        <ul class="file-list" aria-label="Archivos seleccionados">
          @for (f of files(); track f.file) {
            <li class="file-item">
              @if (f.preview) {
                <img class="file-preview" [src]="f.preview" alt="" />
              } @else {
                <i class="fa-solid fa-file file-icon" aria-hidden="true"></i>
              }
              <span class="file-name" [title]="f.name">{{ f.name }}</span>
              <span class="file-size">{{ formatSize(f.size) }}</span>
              @if (!isDisabled()) {
                <button
                  type="button"
                  class="file-remove"
                  (click)="removeFile(f)"
                  [attr.aria-label]="'Eliminar ' + f.name"
                >
                  <i class="fa-solid fa-xmark" aria-hidden="true"></i>
                </button>
              }
            </li>
          }
        </ul>
      }
    </div>
  `,
  styleUrl: './file-input.component.css',
})
export class FileInputComponent implements ControlValueAccessor {
  private readonly platformId = inject(PLATFORM_ID);
  private readonly changeDetectorRef = inject(ChangeDetectorRef);
  readonly inputId = `file-input-${++fileInputSequence}`;

  @ViewChild('fileInput') fileInputRef!: ElementRef<HTMLInputElement>;

  readonly label = input('');
  readonly hint = input('');
  readonly accept = input('');
  readonly multiple = input(false);
  readonly maxSizeMB = input<number>();
  readonly maxPreviewSizeMB = input(2);
  readonly maxPreviewFiles = input(4);
  readonly disabled = input(false);
  private readonly disabledByForm = signal(false);
  readonly error = input('');

  readonly filesChange = output<FileInputFile[]>();

  /** Densidad visual. `compact` conserva el mismo contrato dentro de formularios modales. */
  readonly density = input<FileInputDensity>('comfortable');

  readonly files = signal<FileInputFile[]>([]);
  readonly isDragging = signal(false);
  readonly validationError = signal('');

  isDisabled(): boolean {
    return this.disabled() || this.disabledByForm();
  }

  get visibleError(): string {
    return this.error() || this.validationError();
  }

  private onChange: (v: FileInputFile[]) => void = () => {};
  protected onTouched: () => void = () => {};

  openFileDialog() {
    if (!this.isDisabled()) {
      this.onTouched();
      this.fileInputRef.nativeElement.click();
    }
  }

  onFileChange(event: Event) {
    if (this.isDisabled()) return;
    const input = event.target as HTMLInputElement;
    if (input.files) this.processFiles(Array.from(input.files));
    input.value = '';
  }

  onDragOver(event: DragEvent) {
    event.preventDefault();
    if (!this.isDisabled()) {
      this.isDragging.set(true);
    }
  }

  onDrop(event: DragEvent) {
    event.preventDefault();
    this.isDragging.set(false);
    if (this.isDisabled()) return;
    const dropped = event.dataTransfer?.files;
    if (dropped) this.processFiles(Array.from(dropped));
  }

  private processFiles(rawFiles: File[]) {
    this.onTouched();
    this.validationError.set('');
    const selectedFiles = this.multiple() ? rawFiles : rawFiles.slice(0, 1);
    // Un archivo rechazado DESCARTA la seleccion anterior.
    //
    // Antes se ponia el mensaje de error y se salia sin tocar `files`, asi que lo
    // que hubiera seleccionado antes sobrevivia: el componente seguia mostrando
    // el fichero viejo, el formulario no recibia cambio alguno y el boton de
    // guardar del consumidor seguia habilitado. Lo que se enviaba no era lo que
    // la pantalla senalaba con el error, y en un flujo de archivado documental
    // eso significa guardar el documento equivocado de forma inmutable.
    //
    // Vaciar es la unica lectura en la que lo que se ve y lo que se envia
    // coinciden. Se notifica tambien al formulario, no solo al evento.
    const maxSizeMB = this.maxSizeMB();
    const invalidSize = selectedFiles.find(
      (file) => maxSizeMB !== undefined && file.size > maxSizeMB * 1024 * 1024,
    );
    if (invalidSize) {
      this.rejectSelection(
        `${invalidSize.name} supera el máximo de ${this.maxSizeMB()} MB.`,
      );
      return;
    }

    const invalidType = selectedFiles.find((file) => !this.isAccepted(file));
    if (invalidType) {
      this.rejectSelection(
        `${invalidType.name} no corresponde a los formatos permitidos.`,
      );
      return;
    }

    const processed: FileInputFile[] = selectedFiles.map((file) => ({
      file,
      name: file.name,
      size: file.size,
      type: file.type,
    }));

    this.generateImagePreviews(processed);

    const newFiles = this.multiple() ? [...this.files(), ...processed] : processed;
    this.files.set(newFiles);
    this.onChange(newFiles);
    this.filesChange.emit(newFiles);
  }

  /** Deja el campo vacio y avisa: al formulario y al evento. */
  private rejectSelection(message: string): void {
    this.validationError.set(message);
    this.files.set([]);
    this.onChange([]);
    this.filesChange.emit([]);
  }

  private generateImagePreviews(files: FileInputFile[]): void {
    if (!isPlatformBrowser(this.platformId)) {
      return;
    }

    const maxPreviewFiles = this.maxPreviewFiles();
    const maxFiles = Number.isFinite(maxPreviewFiles)
      ? Math.max(0, Math.trunc(maxPreviewFiles))
      : 0;
    const maxPreviewSizeMB = this.maxPreviewSizeMB();
    const maxSize = Number.isFinite(maxPreviewSizeMB)
      ? Math.max(0, maxPreviewSizeMB)
      : 0;
    const maxBytes = maxSize * 1024 * 1024;
    const existingPreviewCount = this.multiple()
      ? this.files().filter((file) => file.preview).length
      : 0;
    let remaining = Math.max(0, maxFiles - existingPreviewCount);

    for (const item of files) {
      if (remaining === 0) {
        break;
      }
      if (!item.type.startsWith('image/') || item.size > maxBytes) {
        continue;
      }

      remaining -= 1;
      const reader = new FileReader();
      reader.onload = (event) => {
        const preview = event.target?.result;
        if (typeof preview === 'string') {
          item.preview = preview;
          this.files.update((current) => [...current]);
        }
      };
      reader.readAsDataURL(item.file);
    }
  }

  private isAccepted(file: File): boolean {
    const rules = this.accept()
      .split(',')
      .map((rule) => rule.trim().toLowerCase())
      .filter(Boolean);
    if (rules.length === 0) {
      return true;
    }

    const name = file.name.toLowerCase();
    const type = file.type.toLowerCase();
    return rules.some((rule) => {
      if (rule.startsWith('.')) {
        return name.endsWith(rule);
      }
      if (rule.endsWith('/*')) {
        return type.startsWith(rule.slice(0, -1));
      }
      return type === rule;
    });
  }

  removeFile(f: FileInputFile) {
    this.files.update((fs) => fs.filter((x) => x !== f));
    this.onChange(this.files());
    this.filesChange.emit(this.files());
    this.onTouched();
  }

  formatSize(bytes: number): string {
    if (bytes < 1024) return `${bytes} B`;
    if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
    return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
  }

  // ControlValueAccessor
  writeValue(v: FileInputFile[]): void {
    this.files.set(v ?? []);
  }
  registerOnChange(fn: (v: FileInputFile[]) => void): void {
    this.onChange = fn;
  }
  registerOnTouched(fn: () => void): void {
    this.onTouched = fn;
  }
  setDisabledState(d: boolean): void {
    this.disabledByForm.set(d);
    this.changeDetectorRef.markForCheck();
  }
}

