    { value: 'guest', label: 'Invitado' }
  ];

  // ============================================
  // FORM
  // ============================================

  entityForm = this.fb.group({
    name: ['', [Validators.required, Validators.minLength(2)]],
    email: ['', [Validators.required, Validators.email]],
    role: ['user', [Validators.required]],
    status: ['active', [Validators.required]]
  });

  // ============================================
  // COMPUTED
  // ============================================

  /** Current page data */
  items = computed(() => this.listApi.data()?.data ?? []);

  /** Pagination meta */
  meta = computed(() => this.listApi.data()?.meta ?? {
    total: 0,
    page: 1,
    perPage: this.pageSize(),
    totalPages: 1
  });

  /** Number of selected items */
  selectedCount = computed(() => this.selectedItems().size);

  /** Has selected items */
  hasSelection = computed(() => this.selectedCount() > 0);

  // ============================================
  // LIFECYCLE
  // ============================================

  ngOnInit(): void {
    this.loadData();
  }

  // ============================================
  // DATA LOADING
  // ============================================

  loadData(): void {
    const filters = this.filters();
    let filtered = [...FAKE_DB];
    if (filters.searchType && filters.searchValue) {
      const type = filters.searchType;
      const val = filters.searchValue.toLowerCase();
      if (type === 'name') filtered = filtered.filter(e => e.name.toLowerCase().includes(val) || e.email.toLowerCase().includes(val));
      if (type === 'document') filtered = filtered.filter(e => e.id.toLowerCase().includes(val)); // Mock document as id
      if (type === 'regimen') {
        // Mock regimen logic (we don't have regimen in Entity, let's map it randomly or just skip)
        // Let's pretend everyone with role admin is 728, others are CAS (1057)
        filtered = filtered.filter(e => (val === '728' ? e.role === 'admin' : e.role !== 'admin'));
      }
      if (type === 'status') filtered = filtered.filter(e => e.status === val);
    }
    if (filters.status) filtered = filtered.filter(e => e.status === filters.status);
    if (filters.role) filtered = filtered.filter(e => e.role === filters.role);

    const page = this.currentPage();
    const perPage = this.pageSize();
    const start = (page - 1) * perPage;
    const paginated = filtered.slice(start, start + perPage);

    const res: PaginatedResponse<Entity> = {
      data: paginated,
      meta: { total: filtered.length, page, perPage, totalPages: Math.ceil(filtered.length / perPage) }
    };

    this.listApi.execute(of(res).pipe(delay(600)));
  }

  // ============================================
  // PAGINATION
  // ============================================

  onPageChange(page: number): void {
    this.currentPage.set(page);
    this.clearSelection();
    this.loadData();
  }

  // ============================================
  // SEARCH & FILTERS
  // ============================================

  applySearch(): void {
    this.filters.update(f => ({ ...f, searchType: this.selectedSearchType(), searchValue: this.searchValue() }));
    this.currentPage.set(1);
    this.loadData();
  }

  onSearchTypeChange(type: string): void {
    this.selectedSearchType.set(type);
    this.searchValue.set(''); // clear value when type changes
    this.applySearch();
  }

  onSearchValueChange(val: string): void {
    this.searchValue.set(val);
    clearTimeout(this._searchTimeout);
    this._searchTimeout = setTimeout(() => {
      this.applySearch();
    }, 300);
  }

  onStatusFilter(status: string): void {
    this.filters.update(f => ({ ...f, status }));
    this.currentPage.set(1);
    this.loadData();
  }

  onRoleFilter(role: string): void {
    this.filters.update(f => ({ ...f, role }));
    this.currentPage.set(1);
    this.loadData();
  }

  clearFilters(): void {
    this.filters.set({ searchType: '', searchValue: '', status: '', role: '' });
    this.selectedSearchType.set(''); this.searchValue.set('');
    this.currentPage.set(1);
    this.loadData();
  }

  hasActiveFilters(): boolean {
    const f = this.filters();
    return !!(f.searchType || f.searchValue || f.status || f.role);
  }

  // ============================================
  // SELECTION
  // ============================================

  toggleSelectAll(): void {
    if (this.allSelected()) {
      this.clearSelection();
    } else {
      const allIds = new Set<string | number>(this.items().map(item => item.id));
      this.selectedItems.set(allIds);
      this.allSelected.set(true);
    }
  }

  toggleSelect(item: Entity): void {
    const selected = new Set(this.selectedItems());
    if (selected.has(item.id)) {
      selected.delete(item.id);
    } else {
      selected.add(item.id);
    }
    this.selectedItems.set(selected);
    this.allSelected.set(selected.size === this.items().length);
  }

  isSelected(item: Entity): boolean {
    return this.selectedItems().has(item.id);
  }

  clearSelection(): void {
    this.selectedItems.set(new Set());
    this.allSelected.set(false);
  }

  // ============================================
  // CREATE / EDIT
  // ============================================

  openCreateModal(): void {
    this.isEditMode.set(false);
    this.currentItem.set(null);
    this.entityForm.reset({
      name: '',
      email: '',
      role: 'user',
      status: 'active'
    });
    this.showModal.set(true);
  }

  openEditModal(item: Entity): void {
    this.isEditMode.set(true);
    this.currentItem.set(item);
    this.entityForm.patchValue({
      name: item.name,
      email: item.email,
      role: item.role,
      status: item.status
    });
    this.showModal.set(true);
  }

  closeModal(): void {
    this.showModal.set(false);
    this.saveApi.reset();
  }

  onSave(): void {
    if (this.entityForm.invalid) {
      this.entityForm.markAllAsTouched();
      return;
    }

    const formValue = this.entityForm.getRawValue();
    const currentItem = this.currentItem();
    const data: Entity = {
      id: currentItem?.id ?? String(idCounter++),
      createdAt: currentItem?.createdAt ?? new Date().toISOString().split('T')[0],
      ...formValue,
    };

    if (this.isEditMode()) {
      const item = currentItem;
      if (item) {
        const idx = FAKE_DB.findIndex(e => e.id === item.id);
        if (idx !== -1) FAKE_DB[idx] = data;
        this.saveApi.execute(of(data).pipe(delay(800)));
      }
    } else {
      FAKE_DB.unshift(data);
      this.saveApi.execute(of(data).pipe(delay(800)));
    }

    // Check for success
    const checkSave = setInterval(() => {
      if (this.saveApi.success()) {
        clearInterval(checkSave);
        this.closeModal();
        this.loadData();
      }
    }, 100);
  }

  // ============================================
  // DELETE
  // ============================================

  openDeleteModal(item: Entity): void {
    this.itemToDelete.set(item);
    this.showDeleteModal.set(true);
  }

  closeDeleteModal(): void {
    this.showDeleteModal.set(false);
    this.itemToDelete.set(null);
    this.deleteApi.reset();
  }

  confirmDelete(): void {
    const item = this.itemToDelete();
    if (item) {
      const idx = FAKE_DB.findIndex(e => e.id === item.id);
      if (idx !== -1) { FAKE_DB.splice(idx, 1); }
      this.deleteApi.execute(of({ success: true }).pipe(delay(600)));
      const checkDelete = setInterval(() => {
        if (this.deleteApi.success()) {
          clearInterval(checkDelete);
          this.closeDeleteModal();
          this.loadData();
        }
      }, 100);
    }
  }

  // ============================================
  // BULK ACTIONS
  // ============================================

  bulkDelete(): void {
    const ids = Array.from(this.selectedItems());
    if (ids.length === 0) return;

    // TODO: Implement bulk delete API call
    // Example: this.api.post('/bulk-delete', { ids }).subscribe(() => this.loadData());
    this.clearSelection();
  }

  bulkExport(): void {
    const _ids = Array.from(this.selectedItems());
    // TODO: Implement export functionality
    // Example: this.api.downloadFile('/export', { ids: ids.length > 0 ? ids : 'all' });
  }

  // ============================================
  // HELPERS
  // ============================================

  getStatusVariant(status: string): 'success' | 'warning' | 'error' | 'default' {
    switch (status) {
      case 'active': return 'success';
      case 'pending': return 'warning';
      case 'inactive': return 'error';
      default: return 'default';
    }
  }

  getStatusLabel(status: string): string {
    switch (status) {
      case 'active': return 'Activo';
      case 'pending': return 'Pendiente';
      case 'inactive': return 'Inactivo';
      default: return status;
    }
  }

  // ============================================
  // NAVIGATION
  // ============================================

  onPageSizeChange(newSize: number): void {
    this.pageSize.set(newSize);
    this.currentPage.set(1);
    this.loadData();
  }

  goBack(): void {
    this.router.navigate(['/']);
  }

  formatDate(dateString: string): string {
    return new Date(dateString).toLocaleDateString('es-ES', {
      year: 'numeric',
      month: 'short',
      day: 'numeric'
    });
  }

  getFieldError(fieldName: string): string {
    const field = this.entityForm.get(fieldName);
    if (!field || !field.touched || !field.errors) return '';

    if (field.errors['required']) return 'Campo requerido';
    if (field.errors['email']) return 'Email inválido';
    if (field.errors['minlength']) {
      return `Mínimo ${field.errors['minlength'].requiredLength} caracteres`;
    }
    return '';
  }
}

import { Injectable, signal } from '@angular/core';

export type PopupSize = 'sm' | 'md' | 'lg';
export type PopupType = 'info' | 'success' | 'warning' | 'error' | 'confirm';

export interface PopupButton {
  label: string;
  variant?: 'primary' | 'secondary' | 'danger' | 'ghost';
  action: () => void;
  /** Recibe el foco al abrirse el popup. Solo uno por popup. */
  autofocus?: boolean;
  /** Lo que hay que ejecutar si el popup se cierra por Escape o por la aspa. */
  cancels?: boolean;
}

/**
 * Lo que hace falta para preguntar por un acto que se va a ejecutar.
 *
 * `confirmLabel` NO tiene valor por defecto a proposito. Un boton que dice
 * «Confirmar» obliga a leer el titulo para saber que se confirma, y quien lleva
 * cuarenta dialogos al dia ya no lee el titulo. El verbo del acto va en el
 * boton: «Anular la solicitud», «Eliminar el gasto».
 */
export interface PopupConfirmOptions {
  title: string;
  message: string;
  /** El verbo del acto. Obligatorio. */
  confirmLabel: string;
  cancelLabel?: string;
  /** `danger` para lo que no se puede deshacer. */
  tone?: 'default' | 'danger';
  /** Por defecto `cancel`: la salida segura es la que recibe el foco. */
  initialFocus?: 'cancel' | 'confirm';
  onConfirm: () => void;
  onCancel?: () => void;
}

export interface PopupConfig {
  id?: number;
  title: string;
  message?: string;
  type?: PopupType;
  size?: PopupSize;
  icon?: string;
  closable?: boolean;
  closeOnBackdrop?: boolean;
  buttons?: PopupButton[];
  /** Contenido HTML personalizado (opcional) */
  htmlContent?: string;
}

export interface PopupItem extends PopupConfig {
  id: number;
  closing?: boolean;
}

/**
 * Servicio global para mostrar popups/modales dinámicos.
 * Inyectable en root para que sea singleton en toda la aplicación.
 * 
 * @example
 * ```typescript
 * export class MyComponent {
 *   private popup = inject(PopupService);
 * 
 *   showInfo() {
 *     this.popup.info('Información', 'Este es un mensaje informativo');
 *   }
 * 
 *   showConfirm() {
 *     // Una confirmación dice QUÉ va a pasar, no pregunta si se está seguro.
 *     this.popup.confirm({
 *       title: 'Eliminar el gasto del 12/03',
 *       message: 'Se retira del arqueo del día y del reporte de caja. No se puede deshacer.',
 *       confirmLabel: 'Eliminar el gasto',
 *       tone: 'danger',
 *       onConfirm: () => this.delete(),
 *       onCancel: () => {}
 *     });
 *   }
 * }
 * ```
 */
@Injectable({
  providedIn: 'root'
})
export class PopupService {
  private popupId = 0;

  /** Signal público para que el componente lea los popups */
  readonly popups = signal<PopupItem[]>([]);

  /**
   * Muestra un popup con la configuración especificada.
   */
  show(config: PopupConfig): number {
    const id = ++this.popupId;
    const popup: PopupItem = {
      ...config,
      id,
      type: config.type ?? 'info',
      size: config.size ?? 'md',
      closable: config.closable ?? true,
      closeOnBackdrop: config.closeOnBackdrop ?? true
    };

    this.popups.update(p => [...p, popup]);
    return id;
  }

  /** Popup informativo simple */
  info(title: string, message: string): number {
    let id = 0;
    id = this.show({
      title,
      message,
      type: 'info',
      icon: 'fa-solid fa-circle-info',
      buttons: [{ label: 'Aceptar', variant: 'primary', action: () => this.close(id) }]
    });
    return id;
  }

  /** Popup de éxito */
  success(title: string, message: string): number {
    let id = 0;
    id = this.show({
      title,
      message,
      type: 'success',
      icon: 'fa-solid fa-circle-check',
      buttons: [{ label: 'Aceptar', variant: 'primary', action: () => this.close(id) }]
    });
    return id;
  }

  /** Popup de advertencia */
  warning(title: string, message: string): number {
    let id = 0;
    id = this.show({
      title,
      message,
      type: 'warning',
      icon: 'fa-solid fa-triangle-exclamation',
      buttons: [{ label: 'Entendido', variant: 'primary', action: () => this.close(id) }]
    });
    return id;
  }

  /** Popup de error */
  error(title: string, message: string): number {
    let id = 0;
    id = this.show({
      title,
      message,
      type: 'error',
      icon: 'fa-solid fa-circle-xmark',
      buttons: [{ label: 'Cerrar', variant: 'danger', action: () => this.close(id) }]
    });
    return id;
  }

  /**
   * Popup de confirmación con acciones.
   *
   * CAPITULO 7: EL FOCO EMPIEZA EN LA SALIDA SEGURA.
   *
   * Antes el foco se quedaba en el fondo del dialogo y un Intro por inercia
   * ejecutaba el boton primario, que es el que hace la cosa. Ahora el foco
   * arranca en «Cancelar» salvo que se pida lo contrario, y Escape ejecuta la
   * misma cancelacion que el boton —no un cierre mudo que deja al llamador
   * esperando una respuesta que no llega.
   */
  confirm(options: PopupConfirmOptions): number {
    const initialFocus = options.initialFocus ?? 'cancel';
    let id = 0;
    id = this.show({
      title: options.title,
      message: options.message,
      type: 'confirm',
      icon: 'fa-solid fa-question-circle',
      closeOnBackdrop: false,
      buttons: [
        {
          label: options.cancelLabel ?? 'Cancelar',
          variant: 'ghost',
          autofocus: initialFocus === 'cancel',
          cancels: true,
          action: () => { options.onCancel?.(); this.close(id); }
        },
        {
          label: options.confirmLabel,
          variant: options.tone === 'danger' ? 'danger' : 'primary',
          autofocus: initialFocus === 'confirm',
          action: () => { options.onConfirm(); this.close(id); }
        }
      ]
    });
    return id;
  }

  /**
   * Cierra un popup específico por ID.
   */
  close(id: number): void {
    this.popups.update(p =>
      p.map(popup => popup.id === id ? { ...popup, closing: true } : popup)
    );
    setTimeout(() => {
      this.popups.update(p => p.filter(popup => popup.id !== id));
    }, 200);
  }

  /** Cierra todos los popups */
  clear(): void {
    this.popups.set([]);
  }
}

