import { Injectable, signal } from '@angular/core';

export type PopupSize = 'sm' | 'md' | 'lg';
export type PopupType = 'info' | 'success' | 'warning' | 'error' | 'confirm';

export interface PopupButton {
  label: string;
  variant?: 'primary' | 'secondary' | 'danger' | 'ghost';
  action: () => void;
  /** Recibe el foco al abrirse el popup. Solo uno por popup. */
  autofocus?: boolean;
  /** Lo que hay que ejecutar si el popup se cierra por Escape o por la aspa. */
  cancels?: boolean;
}

/**
 * Lo que hace falta para preguntar por un acto que se va a ejecutar.
 *
 * `confirmLabel` NO tiene valor por defecto a proposito. Un boton que dice
 * «Confirmar» obliga a leer el titulo para saber que se confirma, y quien lleva
 * cuarenta dialogos al dia ya no lee el titulo. El verbo del acto va en el
 * boton: «Anular la solicitud», «Eliminar el gasto».
 */
export interface PopupConfirmOptions {
  title: string;
  message: string;
  /** El verbo del acto. Obligatorio. */
  confirmLabel: string;
  cancelLabel?: string;
  /** `danger` para lo que no se puede deshacer. */
  tone?: 'default' | 'danger';
  /** Por defecto `cancel`: la salida segura es la que recibe el foco. */
  initialFocus?: 'cancel' | 'confirm';
  onConfirm: () => void;
  onCancel?: () => void;
}

export interface PopupConfig {
  id?: number;
  title: string;
  message?: string;
  type?: PopupType;
  size?: PopupSize;
  icon?: string;
  closable?: boolean;
  closeOnBackdrop?: boolean;
  buttons?: PopupButton[];
  /** Contenido HTML personalizado (opcional) */
  htmlContent?: string;
}

export interface PopupItem extends PopupConfig {
  id: number;
  closing?: boolean;
}

/**
 * Servicio global para mostrar popups/modales dinámicos.
 * Inyectable en root para que sea singleton en toda la aplicación.
 * 
 * @example
 * ```typescript
 * export class MyComponent {
 *   private popup = inject(PopupService);
 * 
 *   showInfo() {
 *     this.popup.info('Información', 'Este es un mensaje informativo');
 *   }
 * 
 *   showConfirm() {
 *     // Una confirmación dice QUÉ va a pasar, no pregunta si se está seguro.
 *     this.popup.confirm({
 *       title: 'Eliminar el gasto del 12/03',
 *       message: 'Se retira del arqueo del día y del reporte de caja. No se puede deshacer.',
 *       confirmLabel: 'Eliminar el gasto',
 *       tone: 'danger',
 *       onConfirm: () => this.delete(),
 *       onCancel: () => {}
 *     });
 *   }
 * }
 * ```
 */
@Injectable({
  providedIn: 'root'
})
export class PopupService {
  private popupId = 0;

  /** Signal público para que el componente lea los popups */
  readonly popups = signal<PopupItem[]>([]);

  /**
   * Muestra un popup con la configuración especificada.
   */
  show(config: PopupConfig): number {
    const id = ++this.popupId;
    const popup: PopupItem = {
      ...config,
      id,
      type: config.type ?? 'info',
      size: config.size ?? 'md',
      closable: config.closable ?? true,
      closeOnBackdrop: config.closeOnBackdrop ?? true
    };

    this.popups.update(p => [...p, popup]);
    return id;
  }

  /** Popup informativo simple */
  info(title: string, message: string): number {
    let id = 0;
    id = this.show({
      title,
      message,
      type: 'info',
      icon: 'fa-solid fa-circle-info',
      buttons: [{ label: 'Aceptar', variant: 'primary', action: () => this.close(id) }]
    });
    return id;
  }

  /** Popup de éxito */
  success(title: string, message: string): number {
    let id = 0;
    id = this.show({
      title,
      message,
      type: 'success',
      icon: 'fa-solid fa-circle-check',
      buttons: [{ label: 'Aceptar', variant: 'primary', action: () => this.close(id) }]
    });
    return id;
  }

  /** Popup de advertencia */
  warning(title: string, message: string): number {
    let id = 0;
    id = this.show({
      title,
      message,
      type: 'warning',
      icon: 'fa-solid fa-triangle-exclamation',
      buttons: [{ label: 'Entendido', variant: 'primary', action: () => this.close(id) }]
    });
    return id;
  }

  /** Popup de error */
  error(title: string, message: string): number {
    let id = 0;
    id = this.show({
      title,
      message,
      type: 'error',
      icon: 'fa-solid fa-circle-xmark',
      buttons: [{ label: 'Cerrar', variant: 'danger', action: () => this.close(id) }]
    });
    return id;
  }

  /**
   * Popup de confirmación con acciones.
   *
   * CAPITULO 7: EL FOCO EMPIEZA EN LA SALIDA SEGURA.
   *
   * Antes el foco se quedaba en el fondo del dialogo y un Intro por inercia
   * ejecutaba el boton primario, que es el que hace la cosa. Ahora el foco
   * arranca en «Cancelar» salvo que se pida lo contrario, y Escape ejecuta la
   * misma cancelacion que el boton —no un cierre mudo que deja al llamador
   * esperando una respuesta que no llega.
   */
  confirm(options: PopupConfirmOptions): number {
    const initialFocus = options.initialFocus ?? 'cancel';
    let id = 0;
    id = this.show({
      title: options.title,
      message: options.message,
      type: 'confirm',
      icon: 'fa-solid fa-question-circle',
      closeOnBackdrop: false,
      buttons: [
        {
          label: options.cancelLabel ?? 'Cancelar',
          variant: 'ghost',
          autofocus: initialFocus === 'cancel',
          cancels: true,
          action: () => { options.onCancel?.(); this.close(id); }
        },
        {
          label: options.confirmLabel,
          variant: options.tone === 'danger' ? 'danger' : 'primary',
          autofocus: initialFocus === 'confirm',
          action: () => { options.onConfirm(); this.close(id); }
        }
      ]
    });
    return id;
  }

  /**
   * Cierra un popup específico por ID.
   */
  close(id: number): void {
    this.popups.update(p =>
      p.map(popup => popup.id === id ? { ...popup, closing: true } : popup)
    );
    setTimeout(() => {
      this.popups.update(p => p.filter(popup => popup.id !== id));
    }, 200);
  }

  /** Cierra todos los popups */
  clear(): void {
    this.popups.set([]);
  }
}

import { DestroyRef, inject, Injectable, effect, signal } from '@angular/core';

export type Theme = 'light' | 'dark' | 'brand-dark' | 'system';

@Injectable({
  providedIn: 'root'
})
export class ThemeService {
  private readonly destroyRef = inject(DestroyRef);
  private readonly THEME_STORAGE_KEY = 'app-theme';
  private readonly DARK_CLASS = 'dark';

  // Signal para el tema seleccionado
  private readonly selectedTheme = signal<Theme>(this.getInitialTheme());

  // Signal para el tema efectivo (light, dark, o brand-dark)
  private readonly effectiveTheme = signal<'light' | 'dark' | 'brand-dark'>(this.getEffectiveTheme());

  // Signal para saber si está en dark mode actualmente (cualquier variante oscura)
  readonly isDarkMode = signal<boolean>(
    this.effectiveTheme() === 'dark' || this.effectiveTheme() === 'brand-dark'
  );

  // Origen del círculo de transición visual (posición del último click)
  private readonly transitionOrigin = signal<{ x: number; y: number }>({ x: 0, y: 0 });

  // Tema efectivo previo: null = carga inicial (sin animación)
  private previousEffectiveTheme: string | null = null;

  constructor() {
    // Aplicar tema inicial inmediatamente
    if (typeof window !== 'undefined' && typeof document !== 'undefined') {
      this.applyTheme(this.selectedTheme());
    }

    // Efecto: aplicar tema cuando cambia
    effect(() => {
      const theme = this.selectedTheme();
      this.applyTheme(theme);
      this.effectiveTheme.set(this.getEffectiveTheme());
      const effective = this.effectiveTheme();
      this.isDarkMode.set(effective === 'dark' || effective === 'brand-dark');
    });

    // Escuchar cambios en preferencia del SO
    if (typeof window !== 'undefined' && window.matchMedia) {
      const mediaQuery = window.matchMedia('(prefers-color-scheme: dark)');
      const handleChange = () => {
        if (this.selectedTheme() === 'system') {
          this.effectiveTheme.set(this.getEffectiveTheme());
          const effective = this.effectiveTheme();
          this.isDarkMode.set(effective === 'dark' || effective === 'brand-dark');
          this.applyTheme('system');
        }
      };

      mediaQuery.addEventListener('change', handleChange);

      // Cleanup cuando el servicio se destruye
      this.destroyRef.onDestroy(() => {
        mediaQuery.removeEventListener('change', handleChange);
      });
    }
  }

  /**
   * Lee la preferencia guardada. Nunca lanza.
   *
   * EL ACCESO A `localStorage` VA PROTEGIDO, Y NO ES DEFENSA DECORATIVA. El
   * navegador puede denegarlo —cookies de terceros bloqueadas, iframe sin
   * permiso de almacenamiento, modo restrictivo— y en ese caso hasta la simple
   * LECTURA lanza `SecurityError`.
   *
   * Aquí eso no degradaba el tema: lo tumbaba todo. Este servicio es
   * `providedIn: 'root'` y la lectura ocurre al inicializar el campo
   * `selectedTheme`, es decir DURANTE la construcción; la excepción subía por
   * el inyector en el arranque y dejaba la aplicación en pantalla en blanco.
   * Una preferencia visual prescindible no puede impedir que la aplicación
   * abra. Sin persistencia el tema dura lo que la pestaña, que es
   * incomparablemente mejor.
   */
  private readStoredTheme(): Theme | null {
    try {
      return localStorage.getItem(this.THEME_STORAGE_KEY) as Theme | null;
    } catch {
      return null;
    }
  }

  /** Guarda la preferencia si se puede. Ver `readStoredTheme`. */
  private persistTheme(theme: Theme): void {
    try {
      localStorage.setItem(this.THEME_STORAGE_KEY, theme);
    } catch {
      // Sin persistencia el tema dura lo que la pestaña.
    }
  }

  /**
   * Obtiene el tema inicial del localStorage o del SO
   */
  private getInitialTheme(): Theme {
    if (typeof window === 'undefined') return 'light';

    let stored = this.readStoredTheme();

    // Migración automática: forzar el azul corporativo ('brand-dark') a dark neutral ('dark')
    if (stored === 'brand-dark') {
      stored = 'dark';
      this.persistTheme('dark');
    }

    if (stored && ['light', 'dark', 'brand-dark', 'system'].includes(stored)) {
      return stored;
    }

    return 'system';
  }

  /**
   * Obtiene el tema efectivo considerando preferencia del SO
   */
  private getEffectiveTheme(): 'light' | 'dark' | 'brand-dark' {
    if (typeof window === 'undefined') return 'light';

    const selected = this.selectedTheme();

    if (selected === 'system') {
      return window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
    }

    return selected;
  }

  /**
   * Establece el origen visual de la transición (posición del click del usuario).
   */
  setTransitionOrigin(x: number, y: number): void {
    this.transitionOrigin.set({ x, y });
  }

  /**
   * Aplica el tema en el DOM y localStorage.
   * Usa View Transitions API para un circle-reveal fluido desde el punto de click.
   * Fallback CSS para navegadores sin soporte.
   */
  private applyTheme(theme: Theme): void {
    if (typeof window === 'undefined' || typeof document === 'undefined') {
      return;
    }

    const htmlElement = document.documentElement;
    const effectiveTheme: 'light' | 'dark' | 'brand-dark' =
      theme === 'system' ? this.getEffectiveTheme() : theme;

    const doApply = (): void => {
      if (effectiveTheme === 'dark') {
        htmlElement.classList.add(this.DARK_CLASS);
        htmlElement.setAttribute('data-theme', 'dark');
      } else if (effectiveTheme === 'brand-dark') {
        htmlElement.classList.add(this.DARK_CLASS);
        htmlElement.setAttribute('data-theme', 'brand-dark');
      } else {
        htmlElement.classList.remove(this.DARK_CLASS);
        htmlElement.setAttribute('data-theme', 'light');
      }
      this.persistTheme(theme);
    };

    // Carga inicial o tema sin cambio → aplicar directo, sin animación
    const shouldAnimate =
      this.previousEffectiveTheme !== null &&
      this.previousEffectiveTheme !== effectiveTheme;
    this.previousEffectiveTheme = effectiveTheme;

    if (!shouldAnimate) {
      doApply();
      return;
    }

    // ── View Transitions API (Chrome/Edge/Safari) ────────────────────────────
    // Circle-reveal nativo desde el punto de click: sin jank, sin layout thrashing
    if ('startViewTransition' in document) {
      const { x, y } = this.transitionOrigin();
      htmlElement.style.setProperty('--vt-x', `${x}px`);
      htmlElement.style.setProperty('--vt-y', `${y}px`);
      (document as Document & {
        startViewTransition: (cb: () => void) => void;
      }).startViewTransition(doApply);
      return;
    }

    // ── Fallback CSS (Firefox y navegadores sin VT API) ───────────────────────
    htmlElement.classList.add('theme-transitioning');
    doApply();
    requestAnimationFrame(() => {
      setTimeout(() => htmlElement.classList.remove('theme-transitioning'), 200);
    });
  }

  /**
   * Cambiar a tema claro
   */
  setLightTheme(): void {
    this.selectedTheme.set('light');
  }

  /**
   * Cambiar a tema oscuro
   */
  setDarkTheme(): void {
    this.selectedTheme.set('dark');
  }

  /**
   * Cambiar a tema oscuro (Corporativo)
   */
  setBrandDarkTheme(): void {
    this.selectedTheme.set('brand-dark');
  }

  /**
   * Usar preferencia del SO
   */
  setSystemTheme(): void {
    this.selectedTheme.set('system');
  }

  /**
   * Alterna entre claro y oscuro neutral.
   * `brand-dark` queda disponible únicamente como una selección explícita.
   */
  toggleTheme(): void {
    if (this.isDarkMode()) {
      this.setLightTheme();
    } else {
      this.setDarkTheme();
    }
  }

  /**
   * Obtener el tema seleccionado
   */
  getSelectedTheme(): Theme {
    return this.selectedTheme();
  }

  /**
   * Obtener el tema efectivo
   */
  getEffectiveDarkMode(): 'light' | 'dark' | 'brand-dark' {
    return this.effectiveTheme();
  }
}

