  /* === Base Structure === */
  .card {
    display: flex;
    min-width: 0;
    flex-direction: column;
    height: 100%;
    background: var(--surface-background);
    border: 1px solid var(--border-color);
    border-radius: var(--radius-lg);
    box-shadow: var(--shadow-md);
    /* overflow: visible para que tooltips y dropdowns dentro de la card no queden cortados.
       La imagen se clips con overflow: hidden en .card__image directamente. */
    overflow: visible;
    transition: all 200ms ease;
  /* Container query: la card es su propio contexto de contenedor.
     Los hijos pueden adaptar su layout basándose en el ancho de la card,
     no en el viewport (@container en lugar de @media). */
  container-type: inline-size;
  container-name: card;
}

.card:focus-within {
  z-index: 50;
  position: relative;
}

:host {
  display: block;
  width: 100%;
  min-width: 0;
}

  /* Footer se apila verticalmente cuando la card es muy angosta (< 280px) */
  @container card (max-width: 280px) {
    .card__footer {
      flex-direction: column;
      align-items: stretch;
      gap: var(--space-2);
    }
  }

  /* === Variants === */
  .card--default {
    box-shadow: var(--shadow-sm);
  }

  .card--elevated {
    background: var(--surface-elevated);
    border: 1px solid var(--border-color); /* keeping border for depth as requested by user */
    box-shadow: var(--shadow-md);
  }

  .card--elevated:hover {
    box-shadow: var(--shadow-lg);
    transform: translateY(calc(-1 * var(--space-1)));
  }

  .card--outlined {
    background: transparent;
    box-shadow: none;
  }

  .card--filled {
    background: var(--surface-section);
    border: none;
    box-shadow: none;
  }

  .card--interactive {
    cursor: pointer;
    box-shadow: var(--shadow-sm);
  }

  .card--interactive:hover {
    box-shadow: var(--shadow-md);
    transform: translateY(calc(-1 * var(--space-1)));
    border-color: var(--primary-color);
  }

  .card--interactive:focus-visible,
  .card--clickable:focus-visible {
    outline: none;
    box-shadow: var(--shadow-focus-primary);
  }

  .card--clickable {
    cursor: pointer;
  }

  /* === Sizes === */
  .card--sm .card__header,
  .card--sm .card__body,
  .card--sm .card__footer:not(:empty) {
    padding: var(--space-3);
  }

  .card--md .card__header,
  .card--md .card__body,
  .card--md .card__footer:not(:empty) {
    padding: var(--space-4);
  }

  .card--lg .card__header,
  .card--lg .card__body,
  .card--lg .card__footer:not(:empty) {
    padding: var(--space-5);
  }

  /* === Image === */
  .card__image {
    width: 100%;
    overflow: hidden;
    /* Clip la imagen a las esquinas redondeadas de la card (necesario por overflow: visible en .card) */
    border-radius: var(--radius-lg) var(--radius-lg) 0 0;
  }

  .card__image:empty {
    display: none;
  }

  .card__image ::ng-deep img {
    width: 100%;
    height: auto;
    display: block;
    object-fit: cover;
  }

  /* === Header === */
  .card__header {
    display: flex;
    align-items: flex-start;
    gap: var(--space-3);
  }

  .card__icon {
    font-size: var(--text-2xl);
    color: var(--primary-color);
    display: flex;
    align-items: center;
    justify-content: center;
    width: var(--space-10);
    height: var(--space-10);
    background: var(--primary-color-lighter);
    border-radius: var(--radius-md);
    flex-shrink: 0;
  }

  .card__header-text {
    flex: 1;
    min-width: 0;
  }

  .card__title {
    margin: 0;
    font-size: var(--text-lg);
    font-weight: var(--font-weight-emphasis);
    color: var(--text-color);
    line-height: 1.3;
  }

  .card__subtitle {
    margin: var(--space-1) 0 0;
    font-size: var(--text-sm);
    color: var(--text-color-secondary);
    line-height: 1.4;
  }

  /* === Body === */
  .card__body {
    flex: 1;
    min-width: 0;
    font-size: var(--text-md);
    color: var(--text-color);
    line-height: 1.6;
  }

  .card__body:empty {
    display: none;
  }

  /* === Footer === */
  .card__footer {
    display: flex;
    align-items: center;
    justify-content: flex-end;
    gap: var(--space-3);
    border-top: 1px solid var(--border-color);
  }

  .card__footer:empty {
    display: none;
    border-top: none;
  }

  /* === Horizontal Layout === */
  .card--horizontal {
    flex-direction: row;
  }

  .card--horizontal .card__image {
    width: 40%;
    max-width: 200px;
    flex-shrink: 0;
  }

  .card--horizontal .card__image ::ng-deep img {
    height: 100%;
    object-fit: cover;
  }

  /* === Responsive === */
  @media (max-width: 48rem) {
    .card--horizontal {
      flex-direction: column;
    }

    .card--horizontal .card__image {
      width: 100%;
      max-width: none;
    }
  }

