.combobox { position: relative; width: 100%; }
.combobox.combobox-open { z-index: 1000; }

.combobox-label {
  display: block;
  font-size: var(--text-sm);
  font-weight: var(--font-weight-body);
  color: var(--text-color-secondary);
  margin-bottom: var(--space-1);
}

.combobox-control {
  position: relative;
  display: flex;
  align-items: center;
}

.combobox-input {
  width: 100%;
  padding: var(--space-2) var(--space-8) var(--space-2) var(--space-3);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  background: var(--input-bg);
  color: var(--text-color);
  font-size: var(--text-sm);
  line-height: 1.5;
  outline: none;
  transition: border-color 150ms ease, box-shadow 150ms ease;
}

.combobox-input:focus {
  border-color: var(--input-border-focus);
  box-shadow: var(--input-shadow-focus);
}

.combobox-input:disabled {
  background: var(--input-disabled-bg);
  cursor: not-allowed;
  color: var(--input-disabled-text);
}

.combobox-icon, .combobox-clear {
  position: absolute;
  right: var(--space-3);
  color: var(--text-color-muted);
  font-size: var(--text-sm);
  pointer-events: none;
  background: none;
  border: none;
  cursor: pointer;
  padding: 0;
  display: flex;
  align-items: center;
}

.combobox-clear { pointer-events: all; }
.combobox-clear:hover { color: var(--text-color); }

.combobox-dropdown {
  position: absolute;
  top: calc(100% + 4px);
  left: 0;
  right: 0;
  z-index: 1000;
  max-height: 240px;
  overflow-y: auto;
  background: var(--surface-background);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-lg);
  list-style: none;
  margin: 0;
  padding: var(--space-1) 0;
}

.combobox-option {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-2) var(--space-3);
  cursor: pointer;
  font-size: var(--text-sm);
  color: var(--text-color);
  transition: background 100ms ease;
}

.combobox-option:hover,
.combobox-option-highlighted { background: var(--surface-hover); }
.combobox-option-selected { color: var(--primary-color); font-weight: var(--font-weight-body); }
.combobox-option-disabled {
  background: var(--input-disabled-bg);
  color: var(--input-disabled-text);
  cursor: not-allowed;
}

.combobox-option-disabled .combobox-check {
  color: var(--input-disabled-text);
}

.combobox-check { color: var(--primary-color); font-size: var(--text-xs); }

.combobox-empty {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  padding: var(--space-3);
  color: var(--text-color-muted);
  font-size: var(--text-sm);
}

.combobox-error {
  display: block;
  font-size: var(--text-xs);
  color: var(--danger-color-text);
  margin-top: var(--space-1);
}

