  right: 0;
  background: var(--surface-background);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-dropdown);
  z-index: 100;
  max-height: 240px;
  overflow-y: auto;
  animation: dropdownFade 150ms ease;
}

.dropdown-option {
  width: 100%;
  display: flex;
  align-items: center;
  gap: var(--space-2);
  padding: var(--space-2) var(--space-3);
