      </div>

      <div class="setting-info">
        <p>Tema efectivo: <strong>{{ themeService.getEffectiveDarkMode() === 'dark' ? 'Oscuro' : 'Claro' }}</strong></p>
        <p>Almacenado en localStorage: <code>{{ themeService.getSelectedTheme() }}</code></p>
