/* CSS Grid Layout */
.layout-shell {
  display: grid;
  height: 100vh; /* Fallback para navegadores sin soporte dvh */
  height: 100dvh; /* Dynamic viewport height: corrige iOS Safari (barra inferior del navegador) */
  /* Use CSS variable for sidebar width (default 260px) */
  --sidebar-width: 260px;
  grid-template-columns: var(--sidebar-width) 1fr;
  grid-template-rows: auto minmax(0, 1fr) auto;
  grid-template-areas:
    'sidebar header'
    'sidebar content'
    'sidebar footer';
  background-color: var(--surface-section);
  color: var(--text-color);
}

/* Sidebar Area */
.layout-sidebar {
  grid-area: sidebar;
  background-color: var(--sidebar-bg);
  border-right: 1px solid var(--border-color);
  overflow: hidden;
  z-index: 10;
  width: var(--sidebar-width);
  min-width: var(--sidebar-width);
  transition:
    width 0.3s ease,
    min-width 0.3s ease,
    transform 0.3s ease,
    opacity 0.3s ease;
}

/* Sidebar hidden state - desktop only */
@media (min-width: 48rem) {
  .layout-shell.sidebar-hidden {
    grid-template-columns: 0 1fr;
  }

  .layout-shell.sidebar-hidden .layout-sidebar {
    width: 0;
    min-width: 0;
    overflow: hidden;
    border-right: none;
    opacity: 0;
    pointer-events: none;
  }
}

/* Header Area */
.layout-header {
  grid-area: header;
  position: sticky;
  top: 0;
  z-index: 50;
  padding: 0;
  display: flex;
  align-items: center;
  height: 64px;
}

/* Content Area */
.layout-content {
  grid-area: content;
  overflow: hidden;
  padding: 0;
  display: flex;
  flex-direction: column;
}

.layout-footer {
  grid-area: footer;
  min-width: 0;
}

/* Ensure ScrollOverlay takes full space */
.layout-content ::ng-deep app-scroll-overlay {
  flex: 1;
  height: 100%;
  width: 100%;
}

.content-wrapper {
  width: 100%;
  padding: var(--space-6);
  box-sizing: border-box;
}

@media (max-width: 64rem) {
  .content-wrapper {
    padding: var(--space-4);
  }
}

/*
 * Dark mode se maneja automáticamente via tokens semánticos.
 * --surface-section, --surface-background, --border-color, etc.
 * ya tienen valores apropiados para temas oscuros.
 */

/* Responsive - Mobile/Tablet */
@media (max-width: 48rem) {
  .layout-shell {
    grid-template-columns: 1fr;
    grid-template-rows: 64px minmax(0, 1fr) auto;
    grid-template-areas:
      'header'
      'content'
      'footer';
  }

  .layout-sidebar {
    position: fixed;
    top: 64px;
    left: 0;
    bottom: 0;
    width: 260px;
    transform: translateX(-100%);
    transition: transform 0.3s ease;
    box-shadow: var(--shadow-xl);
    z-index: 50;
  }

  /* Cuando se activa el sidebar en móvil (clase toggleada) */
  .layout-sidebar.active {
    transform: translateX(0);
  }

  /* Overlay backdrop for mobile */
  .layout-overlay {
    position: fixed;
    inset: 0;
    background-color: var(--overlay-backdrop);
    z-index: 40;
    opacity: 0;
    pointer-events: none;
    transition: opacity 0.3s ease;
  }

  .layout-overlay.active {
    opacity: 1;
    pointer-events: auto;
  }

  .content-wrapper {
    padding: var(--space-3);
  }
}

/*
  Enlace de salto: fuera de la vista hasta que recibe el foco.

  No se usa `display: none` ni `visibility: hidden` a proposito: las dos lo
  sacarian tambien del orden de tabulacion, que es justo lo contrario de lo que
  este enlace necesita. La tecnica es reducirlo a un pixel recortado, que lo
  mantiene enfocable y anunciable.
*/
.layout-skip-link {
  position: absolute;
  inline-size: 1px;
  block-size: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}

.layout-skip-link:focus-visible,
.layout-skip-link:focus {
  position: fixed;
  inset-block-start: var(--space-2, 0.5rem);
  inset-inline-start: var(--space-2, 0.5rem);
  z-index: 1100;
  inline-size: auto;
  block-size: auto;
  margin: 0;
  padding: var(--space-2, 0.5rem) var(--space-3, 0.75rem);
  overflow: visible;
  clip-path: none;
  border-radius: var(--radius-md, 0.5rem);
  background-color: var(--surface-card, #fff);
  color: var(--text-color, #111);
  box-shadow: var(--shadow-lg, 0 10px 25px rgb(0 0 0 / 25%));
  outline: 2px solid var(--brand-primary-500, #5f295c);
  outline-offset: 2px;
}

