  border-top: 1px solid var(--print-document-border);
}

.print-document-panel__signatures {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 10rem), 1fr));
  gap: var(--space-4);
  padding-top: var(--space-5);
