:host {
  display: block;
  width: 100%;
  position: relative;
  z-index: 1;
}

:host:has(.select2-wrapper.open) {
  z-index: 1000;
}

.select2-wrapper {
  position: relative;
  width: var(--select2-width, 100%);
  min-width: var(--select2-min-width, 15rem);
}

.select2-wrapper.open {
  z-index: 1000;
}

.select2-wrapper.disabled {
  pointer-events: none;
  color: var(--input-disabled-text);
}

.select2-wrapper.disabled .select2-trigger,
.tag-remove:disabled {
  cursor: not-allowed;
}

.select2-wrapper.has-label {
  margin-top: var(--space-3);
}

/* === TRIGGER === */
.select2-trigger {
  position: relative;
  display: flex;
  align-items: center;
  height: var(--control-height);
  padding: var(--space-1) var(--space-3);
  /* Deja sitio al icono: es un ESPACIO, asi que le toca un paso de la
     escala. Estaba en --space-11, que no es un espacio sino el objetivo
     tactil minimo colado en la escala. Capitulo 10. */
  padding-right: var(--space-7);
  background: var(--input-bg);
  border: var(--input-border-width, 1.5px) solid var(--input-border);
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: all 200ms ease;
  font-size: var(--text-sm);
  box-sizing: border-box;
  box-shadow: var(--input-shadow);
  /* FIXED: Permitir clics en Wails */
  --wails-draggable: no-drag;
}

.select2-wrapper.has-label .select2-trigger {
  padding: var(--space-1) var(--space-3);
}

/* === FLOATING LABEL === */
.floating-label {
  position: absolute;
  left: var(--space-3);
  top: 50%;
  transform: translateY(-50%);
  font-size: var(--text-sm);
  color: var(--input-placeholder);
  pointer-events: none;
  transition: all 200ms cubic-bezier(0.4, 0, 0.2, 1);
  background: var(--input-bg);
  padding: 0 var(--space-2);
  white-space: nowrap;
}

.select2-wrapper.focused .floating-label,
.select2-wrapper.has-value .floating-label {
  top: -0.625rem;
  transform: translateY(0);
  font-size: var(--text-xs);
  font-weight: var(--font-weight-body);
  color: var(--info-color-text);
}

/* === MULTI-SELECT FIX === */
.select2-wrapper.multiple .select2-trigger {
  min-height: var(--control-height);
  height: auto;
  padding: var(--space-1) var(--space-3);
  /* Deja sitio al icono: es un ESPACIO, asi que le toca un paso de la
     escala. Estaba en --space-11, que no es un espacio sino el objetivo
     tactil minimo colado en la escala. Capitulo 10. */
  padding-right: var(--space-7);
  align-items: center;
}

.select2-trigger:hover {
  border-color: var(--input-border-focus);
  box-shadow: var(--input-shadow-hover);
}

.select2-wrapper.focused .select2-trigger {
  border-color: var(--input-border-focus);
  box-shadow: var(--input-shadow-focus);
}

.select2-trigger:focus-visible {
  outline: none;
  border-color: var(--input-border-focus);
  box-shadow: var(--input-shadow-focus);
}

.select2-value {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  flex: 1;
  font-size: var(--text-sm);
  color: var(--input-text);
  line-height: normal;
}

.placeholder {
  color: var(--input-placeholder);
}

.select2-arrow {
  position: absolute;
  right: var(--space-3);
  top: 50%;
  transform: translateY(-50%);
  color: var(--text-color-secondary);
  transition: transform 200ms ease;
}

.select2-wrapper.open .select2-arrow {
  transform: translateY(-50%) rotate(180deg);
}

/* === TAGS (Multiple) === */
.select2-tags {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-1);
  flex: 1;
  padding: var(--space-1) 0;
}

.select2-tag {
  display: inline-flex;
  align-items: center;
  gap: var(--space-1);
  padding: var(--space-1) var(--space-2);
  background: var(--info-color-lighter);
  color: var(--info-color-text);
  border-radius: var(--radius-full);
  font-size: var(--text-xs);
  font-weight: var(--font-weight-body);
}

.tag-remove {
  display: flex;
  align-items: center;
  justify-content: center;
  width: var(--space-4);
  height: var(--space-4);
  padding: 0;
  background: none;
  border: none;
  border-radius: 50%;
  font-size: var(--text-sm);
  color: var(--info-color-text);
  cursor: pointer;
  transition: all 150ms ease;
}

.tag-remove:hover {
  background: var(--info-color-lighter);
}

/* === DROPDOWN === */
.select2-dropdown {
  position: absolute;
  top: calc(100% + 4px);
  left: 0;
  right: 0;
  background: var(--dropdown-bg);
  border: 1px solid var(--dropdown-border);
  border-radius: var(--radius-md);
  box-shadow: var(--dropdown-shadow);
  z-index: 10000;
  animation: dropdownSlide 200ms ease;
  overflow: hidden;
  /* FIXED: Permitir clics en Wails */
  --wails-draggable: no-drag;
}

@keyframes dropdownSlide {
  from { opacity: 0; transform: translateY(calc(-1 * var(--space-2))); }
  to { opacity: 1; transform: translateY(0); }
}

/* === SEARCH === */
.select2-search {
  position: relative;
  padding: var(--space-2);
  border-bottom: 1px solid var(--dropdown-border);
}

.search-input {
  width: 100%;
  padding: var(--space-2) var(--space-3);
  padding-left: var(--space-7);
  font-size: var(--text-md);
  border: 1px solid var(--input-border);
  border-radius: var(--radius-sm);
  background: var(--input-bg);
  color: var(--input-text);
  outline: none;
  box-shadow: var(--shadow-xs);
  transition: all 150ms ease;
}

.search-input:hover:not(:focus) {
  border-color: var(--input-border-hover);
  box-shadow: var(--shadow-sm);
}

.search-input:focus {
  border-color: var(--input-border-focus);
  background: var(--input-bg);
  box-shadow: var(--input-shadow-focus);
}

.search-icon {
  position: absolute;
  left: var(--space-4);
  top: 50%;
  transform: translateY(-50%);
  font-size: var(--text-sm);
}

/* === OPTIONS === */
.select2-options {
  max-height: 240px;
  overflow-y: auto;
  scrollbar-width: thin;
  scrollbar-color: var(--scrollbar-thumb) var(--scrollbar-track);
}

/* Custom Scrollbar for dropdown */
.select2-options::-webkit-scrollbar {
  width: 6px;
}
.select2-options::-webkit-scrollbar-track {
  background: var(--scrollbar-track);
}
.select2-options::-webkit-scrollbar-thumb {
  background: var(--scrollbar-thumb);
  border-radius: var(--radius-full);
}
.select2-options::-webkit-scrollbar-thumb:hover {
  background: var(--scrollbar-thumb-hover);
}

.select2-option {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  padding: var(--space-3) var(--space-4);
  font-size: var(--text-md);
  color: var(--dropdown-text, var(--text-color));
  cursor: pointer;
  transition: background 100ms ease;
}



.select2-option:hover:not(.disabled),
.select2-option.highlighted:not(.disabled) {
  background: var(--dropdown-item-hover);
}

.select2-option.selected {
  background: var(--dropdown-item-selected);
  color: var(--info-color-text);
  font-weight: var(--font-weight-body);
}

.select2-option.disabled {
  cursor: not-allowed;
  color: var(--input-disabled-text);
}

.option-icon {
  font-size: var(--text-md);
}

.option-label {
  flex: 1;
}

.check-icon {
  color: var(--info-color-text);
  font-weight: bold;
}

.select2-no-results {
  padding: var(--space-4);
  text-align: center;
  color: var(--text-color-muted);
  font-size: var(--text-sm);
}

