.settings-layout {
  display: flex;
  flex-direction: column;
  gap: var(--space-4);
  padding: var(--space-4);
  max-width: 800px;
  margin: 0 auto;
  width: 100%;
}

/* Avatar section */
.avatar-section {
  display: flex;
  align-items: center;
  gap: var(--space-4);
  margin-bottom: var(--space-2);
}

.avatar-info {
  display: flex;
  flex-direction: column;
  gap: var(--space-1);
}

/* Form */
.responsive-fields {
  margin-bottom: var(--space-4);
}

.password-fields {
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
  max-width: 480px;
  width: 100%;   /* Ocupa el ancho disponible en pantallas estrechas */
  margin: var(--space-4) 0;
}

.form-actions {
  display: flex;
  justify-content: flex-end;
  margin-top: var(--space-4);
  padding-top: var(--space-4);
  border-top: 1px solid var(--border-color);
}

/* Notifications */
.notif-list {
  display: flex;
  flex-direction: column;
}

.notif-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: var(--space-3) 0;
  gap: var(--space-4);
  flex-wrap: wrap; /* El toggle cae debajo del texto en pantallas muy estrechas */
}

.notif-info {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

/* Appearance */
.appearance-section {
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
}

.theme-switcher-wrapper {
  margin-top: var(--space-2);
}

/* app-row ya colapsa columns a 1fr en @media (max-width: 40rem) automáticamente.
   Esta regla es un fallback explícito para elementos de grid manuales. */
@media (max-width: 40rem) {
  .responsive-fields {
    grid-template-columns: 1fr;
  }
}

