:host {
  display: block;
  height: 100%;
}

.sidebar-container {
  height: 100%;
  display: flex;
  flex-direction: column;
  padding: var(--space-6) var(--space-4);
  background-color: var(--sidebar-bg);
}

/* Logo */
.sidebar-logo {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  padding: 0 var(--space-2) var(--space-8) var(--space-2);
  color: var(--primary-color);
  font-size: var(--icon-md);
  font-weight: var(--font-weight-body);
}

.logo-emoji {
  font-size: var(--text-2xl);
}

.font-bold {
  font-weight: var(--font-weight-title);
}

/* Nav */
.sidebar-nav-overlay {
  display: block;
  flex: 1;
  min-height: 0;
}

.sidebar-nav {
  height: 100%;
  min-height: 0;
  overflow-y: auto;
  overflow-x: hidden;
  overscroll-behavior: contain;
}

.nav-list {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: var(--space-1);
}

.nav-list--children {
  padding-inline-start: var(--space-4);
  margin-top: var(--space-1);
}

.nav-link {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  padding: var(--space-3) var(--space-4);
  border-radius: var(--radius-md);
  color: var(--text-color-secondary);
  text-decoration: none;
  border: none;
  background: transparent;
  width: 100%;
  text-align: left;
  transition: all 200ms ease;
  font-weight: var(--font-weight-body);
}

.nav-link:hover {
  background-color: var(--hover-background-subtle);
  color: var(--text-color);
}

.nav-link.active {
  background-color: var(--primary-color-lighter);
  color: var(--primary-color-dark);
}

.nav-icon {
  width: var(--space-5);
  flex-shrink: 0;
  font-size: var(--text-xl);
  text-align: center;
  color: var(--sidebar-icon-color, currentColor);
}

.nav-label {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-2);
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.nav-label-text {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  text-transform: uppercase;
  white-space: nowrap;
}

.nav-chevron {
  flex-shrink: 0;
  margin-left: auto;
  font-size: var(--text-xs);
  transition: transform 200ms ease;
}

.nav-chevron.expanded {
  transform: rotate(180deg);
}

.nav-link--child {
  padding-block: var(--space-2);
  font-size: var(--text-sm);
}

.nav-badge {
  padding: var(--space-1) var(--space-2);
  font-size: var(--text-xs);
  font-weight: var(--font-weight-emphasis);
  background-color: var(--danger-color);
  color: var(--text-color-on-primary);
  border-radius: var(--radius-full);
  flex-shrink: 0;
}

/* Footer / User Profile */
.sidebar-footer {
  padding-top: var(--space-4);
  border-top: 1px solid var(--border-color);
  margin-top: var(--space-4);
}

.user-profile {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  padding: var(--space-2);
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: background-color 200ms ease;
}

.user-profile:hover {
  background-color: var(--hover-background-subtle);
}

.avatar {
  width: var(--avatar-size-md, 2.5rem);
  height: var(--avatar-size-md, 2.5rem);
  background-color: var(--primary-color-light);
  border-radius: var(--radius-full);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: var(--text-xl);
}

.user-info {
  display: flex;
  flex-direction: column;
  line-height: 1.2;
}

.user-name {
  font-size: var(--text-sm);
  font-weight: var(--font-weight-emphasis);
  color: var(--text-color);
}

.user-role {
  font-size: var(--text-xs);
  color: var(--text-color-secondary);
}

/* Dark Mode handling is now automatic via semantic variables */

/* Collapsed State */
.sidebar-container.collapsed {
  padding: var(--space-6) var(--space-2);
  align-items: center;
}
.sidebar-container.collapsed .sidebar-logo {
  justify-content: center;
  padding: 0 0 var(--space-8) 0;
}
.sidebar-container.collapsed .nav-link {
  justify-content: center;
  padding: var(--space-3);
}
.sidebar-container.collapsed .nav-list--children {
  display: none;
}
.sidebar-container.collapsed .user-profile {
  justify-content: center;
  padding: var(--space-2);
}

