/* Host display block needed for % widths to work */
:host {
  display: block;
  width: 100%;
}

.skeleton {
  background: linear-gradient(90deg,
    var(--skeleton-gradient-start) 25%,
    var(--skeleton-gradient-mid) 50%,
    var(--skeleton-gradient-start) 75%
  );
  background-size: 200% 100%;
  animation: shimmer 1.5s infinite ease-in-out;
  border-radius: var(--radius-sm);
  height: var(--skeleton-height, auto);
  width: var(--skeleton-width, auto);
}

.skeleton-text {
  height: var(--skeleton-height, var(--space-4));
  width: var(--skeleton-width, auto);
  border-radius: var(--radius-sm);
}

.skeleton-circular {
  height: var(--skeleton-height, var(--space-8));
  width: var(--skeleton-width, var(--space-8));
  border-radius: 50%;
}

.skeleton-rectangular {
  height: var(--skeleton-height, var(--skeleton-rectangular-block-size));
  width: var(--skeleton-width, 100%);
  border-radius: var(--radius-md);
}

.skeleton-card-media {
  block-size: var(--skeleton-card-media-block-size);
}

.skeleton-card-title {
  inline-size: var(--skeleton-card-title-inline-size);
  block-size: var(--space-4);
}

.skeleton-card-line {
  inline-size: var(--skeleton-card-line-inline-size);
  block-size: var(--space-3);
}

.skeleton-card-line-short {
  inline-size: var(--skeleton-card-line-short-inline-size);
  block-size: var(--space-3);
}

.skeleton-avatar {
  inline-size: var(--skeleton-avatar-size);
  block-size: var(--skeleton-avatar-size);
  flex: 0 0 var(--skeleton-avatar-size);
}

.skeleton-avatar-title {
  inline-size: var(--skeleton-avatar-title-inline-size);
  block-size: var(--text-sm);
}

.skeleton-avatar-subtitle {
  inline-size: var(--skeleton-avatar-subtitle-inline-size);
  block-size: var(--space-3);
}

.skeleton-card {
  background: var(--skeleton-card-bg);
  border: 1px solid var(--skeleton-card-border);
  border-radius: var(--radius-lg);
  overflow: hidden;
}

.skeleton-card-content {
  padding: var(--space-4);
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
}

.skeleton-avatar-text {
  display: flex;
  align-items: center;
  gap: var(--space-3);
}

.skeleton-text-group {
  display: flex;
  flex-direction: column;
  gap: var(--space-1);
}

@keyframes shimmer {
  0% { background-position: 200% 0; }
  100% { background-position: -200% 0; }
}

@media (prefers-reduced-motion: reduce) {
  .skeleton {
    animation: none;
    background-position: 0 0;
  }
}

/*
 * Dark mode se maneja automáticamente via tokens semánticos.
 * --skeleton-gradient-start/mid y --skeleton-card-bg/border
 * ya tienen valores apropiados para temas oscuros.
 */

:host { display: inline-flex; align-items: center; justify-content: center; }

.visually-hidden {
  position: absolute;
  width: var(--border-width-thin);
  height: var(--border-width-thin);
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}

.spinner {
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

/* Sizes */
.spinner--xs  { --sz: var(--icon-xs); --border: var(--border-width-thin); }
.spinner--sm  { --sz: var(--icon-sm); --border: var(--border-width-medium); }
.spinner--md  { --sz: var(--icon-md); --border: var(--border-width-medium); }
.spinner--lg  { --sz: var(--icon-lg); --border: var(--border-width-thick); }
.spinner--xl  { --sz: var(--space-7); --border: var(--space-1); }

/* Variants — track color */
.spinner--primary .spinner__ring  { border-color: var(--primary-color-lighter); border-top-color: var(--primary-color); }
.spinner--secondary .spinner__ring { border-color: var(--secondary-color-lighter); border-top-color: var(--secondary-color); }
.spinner--white .spinner__ring    { border-color: var(--border-color); border-top-color: var(--gray-0); }
.spinner--current .spinner__ring  { border-color: transparent; border-top-color: currentColor; }

.spinner__ring {
  display: block;
  width: var(--sz, var(--icon-md));
  height: var(--sz, var(--icon-md));
  border-width: var(--border, var(--border-width-medium));
  border-style: solid;
  border-radius: var(--radius-full);
  animation: spin 0.7s linear infinite;
}

@keyframes spin {
