  position: relative;
  z-index: 1;
  flex: 1 1 0;
  min-width: 0;
}

.step.disabled {
  cursor: not-allowed;
  color: var(--input-disabled-text);
}

/* STEP INDICATOR (CIRCLE) */
.step-indicator {
  width: var(--touch-target-min);
  height: var(--touch-target-min);
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: var(--surface-background);
  color: var(--text-color-secondary);
  font-size: var(--text-md);
  font-weight: var(--font-weight-title);
  border: var(--space-1) solid var(--border-color);
  transition: all 300ms cubic-bezier(0.4, 0, 0.2, 1);
  flex-shrink: 0;
  box-shadow: var(--shadow-xs);
}

/* Active State */
.step.active .step-indicator {
  background: var(--primary-color);
  color: var(--text-color-on-primary);
  border-color: var(--primary-color);
  transform: scale(1.1);
  box-shadow: var(--shadow-glow-primary);
}

/* Completed State */
.step.completed .step-indicator {
  background: var(--success-color);
  border-color: var(--success-color);
  color: var(--text-color-on-primary);
}

.step-check {
  font-size: var(--text-md);
  font-weight: var(--font-weight-display);
}

/* TEXT CONTENT */
.step-content {
  display: flex;
  flex-direction: column;
  gap: var(--space-1);
  min-height: var(--touch-target-min);
  justify-content: center;
  min-width: 0;
  flex: 1 1 0;
}

.step-label {
  font-size: var(--text-md);
  font-weight: var(--font-weight-emphasis);
  color: var(--text-color-secondary);
  transition: color 200ms ease;
  word-break: break-word;
  overflow-wrap: break-word;
}

/* Horizontal mode: indicator on top, label centered below */
.stepper:not(.stepper-vertical) .step {
  flex-direction: column;
  align-items: center;
  gap: var(--space-2, var(--space-2));
}

.stepper:not(.stepper-vertical) .step-content {
  flex: 0 0 auto;
  min-height: auto;
  align-items: center;
  text-align: center;
}

.stepper:not(.stepper-vertical) .step-label {
  text-align: center;
  white-space: normal;
  word-break: break-word;
  overflow-wrap: break-word;
}

.stepper:not(.stepper-vertical) .step-description,
.stepper:not(.stepper-vertical) .step-optional {
  text-align: center;
}

.step.active .step-label {
  color: var(--primary-color);
  font-weight: var(--font-weight-title);
}

.step.completed .step-label {
  color: var(--text-color);
}

.step-description {
  font-size: var(--text-sm);
  color: var(--text-color-muted);
  line-height: 1.4;
}

.step-optional {
  font-size: var(--text-xs);
  color: var(--text-color-muted);
  font-style: italic;
  margin-top: calc(-1 * var(--space-1));
}

/* CONNECTOR LINES */
.step-connector {
  flex: 0 0 var(--space-6);
  height: var(--space-1);
  min-width: var(--space-4);
  margin: var(--space-5, 1.375rem) var(--space-1) 0;
  background: var(--border-color);
  transition: background 300ms ease;
  border-radius: var(--radius-xs, 4px);
}

.step-connector.completed {
  background: var(--success-color);
}

/* Vertical tweaks */
.stepper-vertical .step {
  flex-direction: row;
}

.stepper-vertical .step-connector {
  width: var(--space-1);
  height: var(--space-10, 2.5rem);
  min-width: var(--space-1);
  margin: var(--space-1) 0 var(--space-1) var(--space-5, 1.375rem);
}

/*
 * Dark mode se maneja automáticamente via tokens semánticos.
 * --surface-background, --border-color, --primary-color, --shadow-glow-primary
 * ya tienen valores apropiados para temas oscuros.
 */

/* RESPONSIVE: Compact mobile layout */
@media (max-width: 48rem) {
  .stepper {
    flex-direction: column;
    align-items: stretch;
    gap: 0;
  }

  .stepper .step {
    flex-direction: row;
    gap: var(--space-3);
    padding: var(--space-2) 0;
  }

  .stepper .step-indicator {
    width: var(--space-6);
    height: var(--space-6);
    font-size: var(--text-sm);
  }

  .stepper .step-label {
    font-size: var(--text-sm);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    max-width: 200px;
  }

  .stepper .step-description,
  .stepper .step-optional {
    display: none;
  }

  .stepper .step-connector {
    width: var(--space-1);
    height: var(--space-6);
    min-width: var(--space-1);
    margin: 0 0 0 var(--space-4, 0.9375rem);
  }
}

