import { Component, signal, ContentChildren, QueryList, AfterContentInit, ElementRef, ViewChild, HostBinding, input, output } from '@angular/core';


/**
 * Individual tab content panel.
 * Must be used as child of `app-tabs`.
 */
@Component({
  selector: 'app-tab',
  standalone: true,
  template: `<ng-content></ng-content>`,
  styleUrl: './tab.component.css'
})
export class TabComponent {
  /** Tab label displayed in the header */
  readonly label = input('');
  /** Emoji icon (optional) */
  readonly icon = input<string>();
  /** CSS icon class (e.g., FontAwesome) */
  readonly iconClass = input<string>();
  /** Whether this tab is disabled */
  readonly disabled = input(false);

  @HostBinding('class.active') active = false;
}

/**
 * Tab container component for organizing content into tabbed sections.
 * 
 * @example
 * ```html
 * <app-tabs (tabChange)="onTabChange($event)">
 *   <app-tab label="General" icon="⚙️">Content 1</app-tab>
 *   <app-tab label="Profile" icon="👤">Content 2</app-tab>
 *   <app-tab label="Disabled" [disabled]="true">Disabled content</app-tab>
 * </app-tabs>
 * ```
 */
@Component({
  selector: 'app-tabs',
  standalone: true,
  imports: [],
  template: `
    <div class="tabs-container">
      <div class="tabs-header" #tabsHeader role="tablist" aria-label="Tabs">
        @for (tab of tabs; track tab.label(); let i = $index) {
          <button 
            type="button"
            class="tab-button"
            role="tab"
            [id]="'tab-' + i"
            [attr.aria-selected]="activeIndex() === i"
            [attr.aria-controls]="'tabpanel-' + i"
            [attr.tabindex]="activeIndex() === i ? 0 : -1"
            [class.active]="activeIndex() === i"
            [class.disabled]="tab.disabled()"
            (click)="!tab.disabled() && selectTab(i, $event)"
          >
            @if (tab.iconClass()) {
              <i [class]="tab.iconClass()" class="tab-icon" aria-hidden="true"></i>
            } @else if (tab.icon()) {
              <span class="tab-icon" aria-hidden="true">{{ tab.icon() }}</span>
            }
            {{ tab.label() }}
          </button>
        }
      </div>
      <div 
        class="tabs-content"
        role="tabpanel"
        [id]="'tabpanel-' + activeIndex()"
        [attr.aria-labelledby]="'tab-' + activeIndex()"
      >
        <ng-content></ng-content>
      </div>
    </div>
  `,
  styleUrl: './tabs.component.css'
})
export class TabsComponent implements AfterContentInit {
  @ContentChildren(TabComponent) tabComponents!: QueryList<TabComponent>;
  readonly defaultIndex = input(0);
  readonly tabChange = output<number>();

  activeIndex = signal(0);
  tabs: TabComponent[] = [];

  @ViewChild('tabsHeader', { static: false }) tabsHeader!: ElementRef<HTMLElement>;

  ngAfterContentInit() {
    this.tabs = this.tabComponents.toArray();
    this.activeIndex.set(this.defaultIndex());
    this.updateTabs();
  }

  private updateTabs() {
    this.tabs.forEach((tab, i) => tab.active = i === this.activeIndex());
  }

  selectTab(index: number, event?: MouseEvent) {
    this.activeIndex.set(index);
    this.updateTabs();
    this.tabChange.emit(index);

    // Auto-scroll horizontalmente (sin afectar scroll vertical del padre)
    if (event?.target && this.tabsHeader) {
      const button = event.target as HTMLElement;
      const container = this.tabsHeader.nativeElement;

      // Calcular posición para centrar el botón
      const scrollLeft = button.offsetLeft - (container.clientWidth / 2) + (button.clientWidth / 2);

      container.scrollTo({
        left: Math.max(0, scrollLeft),
        behavior: 'smooth'
      });
    }
  }
}

import { ChangeDetectionStrategy, Component, computed, input, output } from '@angular/core';

export type TableActionName =
  | 'view'
  | 'edit'
  | 'print'
  | 'reverse'
  | 'channels'
  | 'reset-password'
  | 'activate'
  | 'deactivate'
  | 'renew'
  | 'select'
  | 'late-fee'
  | 'delete'
  | 'custom';

export type TableActionTone =
  | 'neutral'
  | 'primary'
  | 'info'
  | 'success'
  | 'warning'
  | 'danger';
export type TableActionSize = 'sm' | 'md' | 'lg';

const ICONS: Readonly<Record<TableActionName, string>> = {
  view: 'fa-eye',
  edit: 'fa-pen-to-square',
  print: 'fa-print',
  reverse: 'fa-rotate-left',
  channels: 'fa-mobile-screen-button',
  'reset-password': 'fa-key',
  activate: 'fa-circle-check',
  deactivate: 'fa-circle-xmark',
  renew: 'fa-clock-rotate-left',
  select: 'fa-hand-pointer',
  'late-fee': 'fa-file-invoice-dollar',
  delete: 'fa-trash-can',
  custom: 'fa-ellipsis',
};

const TONES: Readonly<Record<TableActionName, TableActionTone>> = {
  view: 'info',
  edit: 'primary',
  print: 'primary',
  reverse: 'danger',
  channels: 'info',
  'reset-password': 'warning',
  activate: 'success',
  deactivate: 'danger',
  renew: 'warning',
  select: 'primary',
  'late-fee': 'warning',
  delete: 'danger',
  custom: 'neutral',
};

/** Acción iconográfica individual para grillas y listas compactas. */
@Component({
  selector: 'app-table-action, prest-table-action',
  changeDetection: ChangeDetectionStrategy.OnPush,
  templateUrl: './table-action.html',
  styleUrl: './table-action.scss',
})
export class TableAction {
  readonly action = input<TableActionName>('view');
  readonly label = input.required<string>();
  /** Clase Font Awesome preferida. Acepta `print`, `fa-print` o clases completas. */
  readonly iconClass = input<string | null>(null);
  /** @deprecated Use iconClass. Se conserva para consumidores anteriores. */
  readonly icon = input<string | null>(null);
  readonly tone = input<TableActionTone | null>(null);
  readonly size = input<TableActionSize>('md');
  readonly disabled = input(false);
  readonly loading = input(false);
  readonly selected = input<boolean | null>(null);
  readonly triggered = output<MouseEvent>();

  protected readonly renderedIconClasses = computed(() =>
    resolveTableActionIcon(this.action(), this.iconClass() ?? this.icon()),
  );
  protected readonly toneClass = computed(
    () => `table-action table-action--${this.tone() ?? TONES[this.action()]} table-action--${this.size()}`,
  );

  protected onClick(event: MouseEvent): void {
    if (!this.disabled() && !this.loading()) {
      this.triggered.emit(event);
    }
  }
}

const FONT_AWESOME_STYLE_CLASSES = new Set([
  'fa-solid',
  'fa-regular',
  'fa-light',
  'fa-thin',
  'fa-duotone',
  'fa-brands',
  'fa-sharp',
]);

/** Normaliza alias de iconos sin convertir una acción válida en el fallback de tres puntos. */
export function normalizeTableActionIcon(
  value: string | null | undefined,
  fallback: string,
): string {
  const raw = value?.trim() || fallback;
  const tokens = raw.split(/\s+/).filter(Boolean);
  const style = tokens.find((token) => FONT_AWESOME_STYLE_CLASSES.has(token)) ?? 'fa-solid';
  const glyph =
    tokens.find(
      (token) => token.startsWith('fa-') && !FONT_AWESOME_STYLE_CLASSES.has(token),
    ) ?? `fa-${tokens.find((token) => !token.startsWith('fa-')) ?? fallback.replace(/^fa-/, '')}`;

  return `${style} ${glyph}`;
}

/** Resuelve el glifo semántico de una acción y admite una sobreescritura explícita. */
export function resolveTableActionIcon(
  action: TableActionName,
  value?: string | null,
): string {
  return normalizeTableActionIcon(value, ICONS[action]);
}

/** Comparte el tono semántico con grupos de acciones y otros consumidores Atomic. */
export function resolveTableActionTone(action: TableActionName): TableActionTone {
  return TONES[action];
}

