  height: 100%;
  background-color: var(--surface-background);
  border-bottom: 1px solid var(--border-color);
  transition: background-color 0.3s ease, border-color 0.3s ease;
}

.topbar-container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  height: 100%;
  padding: 0 var(--space-6);
}

.topbar-left {
  display: flex;
  align-items: center;
  gap: var(--space-4);
  flex-shrink: 0;
}

.topbar-right {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  flex-shrink: 0;
  margin-left: auto;
}

.topbar-icon {
  font-size: var(--topbar-action-icon-size);
}

/* Sidebar Toggle Button */
.sidebar-toggle {
  display: flex;
  align-items: center;
  justify-content: center;
  width: var(--control-height);
  height: var(--control-height);
  padding: 0;
  background: transparent;
  border: none;
  border-radius: var(--radius-md);
  color: var(--text-color-secondary);
  cursor: pointer;
  transition: all 0.2s ease;
}

.sidebar-toggle:hover {
  background: var(--surface-hover);
  color: var(--primary-color);
}

.page-title {
  margin: 0;
  font-size: var(--icon-md);
  font-weight: var(--font-weight-emphasis);
  color: var(--text-color);
  line-height: 1.2;
}

/* Action Buttons (Notifications, etc.) */
.topbar-action {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  width: var(--control-height);
  height: var(--control-height);
  padding: 0;
  background: transparent;
  border: none;
  border-radius: var(--radius-md);
  color: var(--text-color-secondary);
  cursor: pointer;
  transition: all 0.2s ease;
}

.topbar-action:hover {
  background: var(--surface-hover);
  color: var(--primary-color);
}

/* Notification Badge */
.notification-badge {
  position: absolute;
  top: 0;
  right: 0;
  min-width: var(--space-4);
  height: var(--space-4);
  padding: 0 var(--space-1);
  font-size: var(--text-2xs);
  font-weight: var(--font-weight-emphasis);
  color: var(--text-color-on-primary);
  background: var(--danger-color);
  border-radius: var(--radius-full);
  display: flex;
  align-items: center;
  justify-content: center;
}

/* User Avatar */
.user-avatar {
  display: flex;
  align-items: center;
  justify-content: center;
  width: var(--control-height);
  height: var(--control-height);
  padding: 0;
  background: linear-gradient(135deg, var(--primary-color), var(--primary-color-dark));
  border: none;
  border-radius: 50%;
  cursor: pointer;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.user-avatar:hover {
  transform: scale(1.05);
  box-shadow: var(--shadow-glow-primary);
}

.avatar-initials {
  font-size: var(--text-xs);
  font-weight: var(--font-weight-emphasis);
  color: var(--text-color-on-primary);
  text-transform: uppercase;
}

/*
 * Dark mode se maneja automáticamente via tokens semánticos.
 * --surface-background, --border-color, --surface-hover, etc.
 * ya tienen valores apropiados para temas oscuros.
 */

/* RESPONSIVE: Compact topbar on mobile */
@media (max-width: 48rem) {
  .topbar-container {
    padding: 0 var(--space-3);
    gap: var(--space-2);
  }

  .topbar-left {
    flex-shrink: 1;
    min-width: 0;
    gap: var(--space-2);
  }

  .page-title {
    font-size: var(--text-md);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    max-width: var(--topbar-title-max-inline-size);
  }

  .topbar-right {
    flex-shrink: 0;
    gap: var(--space-1);
  }

  /* Iconos más pequeños */
  .topbar-right ::ng-deep app-icon-button {
    transform: scale(0.9);
  }
}

@media (max-width: 35rem) {
  .topbar-right ::ng-deep app-language-switcher {
    display: none;
  }

  .page-title {
    max-width: clamp(
      var(--topbar-title-compact-min-inline-size),
      30vw,
      var(--topbar-title-compact-max-inline-size)
    );
  }
}

